// Icon Initialization Script
// This script injects SVG icons into placeholder elements throughout the UI

(function() {
    'use strict';

    // Wait for DOM and icons.js to load
    function initIcons() {
        if (typeof Icons === 'undefined') {
            console.warn('Icons library not loaded yet, retrying...');
            setTimeout(initIcons, 100);
            return;
        }

        // Edit Profile Button
        const editBtn = document.querySelector('#editProfileBtn');
        if (editBtn && !editBtn.querySelector('svg')) {
            editBtn.innerHTML = Icons.edit;
        }

        // Location Icon
        const locationIcon = document.querySelector('.location-icon');
        if (locationIcon && !locationIcon.querySelector('svg')) {
            locationIcon.innerHTML = Icons.mapPin;
        }

        // Stat Card Icons
        const statCards = document.querySelectorAll('.stat-card');
        statCards.forEach(card => {
            const iconEl = card.querySelector('.stat-icon');
            if (!iconEl || iconEl.querySelector('svg')) return;

            if (card.classList.contains('positive-votes')) {
                iconEl.innerHTML = Icons.thumbsUp;
            } else if (card.classList.contains('negative-votes')) {
                iconEl.innerHTML = Icons.thumbsDown;
            } else if (card.classList.contains('streak-card')) {
                iconEl.innerHTML = Icons.flame;
            }
        });

        // Action Button Icons
        const requestVouchBtn = document.querySelector('#requestVouchBtn .btn-icon-left');
        if (requestVouchBtn && !requestVouchBtn.querySelector('svg')) {
            requestVouchBtn.innerHTML = Icons.messageCircle;
        }

        const shareProfileBtn = document.querySelector('#shareProfileBtn .btn-icon-left');
        if (shareProfileBtn && !shareProfileBtn.querySelector('svg')) {
            shareProfileBtn.innerHTML = Icons.share;
        }

        // Vote Button Icons
        const voteButtons = document.querySelectorAll('.vote-btn');
        voteButtons.forEach(btn => {
            const iconEl = btn.querySelector('.vote-icon');
            if (!iconEl || iconEl.querySelector('svg')) return;

            if (btn.classList.contains('vote-positive')) {
                iconEl.innerHTML = Icons.thumbsUp;
            } else if (btn.classList.contains('vote-negative')) {
                iconEl.innerHTML = Icons.thumbsDown;
            }
        });

        // Disclaimer Icon
        const disclaimerIcon = document.querySelector('.disclaimer-icon');
        if (disclaimerIcon && !disclaimerIcon.querySelector('svg')) {
            disclaimerIcon.innerHTML = Icons.alertCircle;
        }

        // Submit Vote Button Icon
        const submitVouchBtn = document.querySelector('#submitVouchBtn .btn-icon-left');
        if (submitVouchBtn && !submitVouchBtn.querySelector('svg')) {
            submitVouchBtn.innerHTML = Icons.check;
        }

        // Community View Tab Icons
        const viewTabs = document.querySelectorAll('.view-tab-btn');
        viewTabs.forEach(tab => {
            const iconEl = tab.querySelector('.tab-icon');
            if (!iconEl || iconEl.querySelector('svg')) return;

            const view = tab.dataset.view;
            if (view === 'activity') {
                iconEl.innerHTML = Icons.activity;
            } else if (view === 'users') {
                iconEl.innerHTML = Icons.users;
            } else if (view === 'leaderboards') {
                iconEl.innerHTML = Icons.trophy;
            }
        });

        // Search Icon
        const searchIcon = document.querySelector('.search-icon');
        if (searchIcon && !searchIcon.querySelector('svg')) {
            searchIcon.innerHTML = Icons.search;
        }

        // Filter Button Icons
        const filterButtons = document.querySelectorAll('.filter-btn');
        filterButtons.forEach(btn => {
            const iconEl = btn.querySelector('.filter-icon');
            if (!iconEl || iconEl.querySelector('svg')) return;

            const filter = btn.dataset.filter;
            if (filter === 'top_tier') {
                iconEl.innerHTML = Icons.crown;
            } else if (filter === 'endorsed') {
                iconEl.innerHTML = Icons.shield;
            } else if (filter === 'trusted') {
                iconEl.innerHTML = Icons.verified;
            }
        });

        // Save Changes Button Icons (all modals)
        const saveButtons = document.querySelectorAll('.btn-primary.btn-large .btn-icon-left');
        saveButtons.forEach(btn => {
            if (!btn.querySelector('svg')) {
                btn.innerHTML = Icons.save;
            }
        });

        // Copy Link Button
        const copyLinkBtn = document.querySelector('#copyLinkBtn .btn-icon-left');
        if (copyLinkBtn && !copyLinkBtn.querySelector('svg')) {
            copyLinkBtn.innerHTML = Icons.copy;
        }

        // Telegram Share Button
        const telegramShareBtn = document.querySelector('#telegramShareBtn .btn-icon-left');
        if (telegramShareBtn && !telegramShareBtn.querySelector('svg')) {
            telegramShareBtn.innerHTML = Icons.send;
        }

        // Modal Close Buttons
        const closeButtons = document.querySelectorAll('.modal .close');
        closeButtons.forEach(btn => {
            if (!btn.querySelector('svg') && btn.textContent === '×') {
                btn.innerHTML = Icons.x;
            }
        });

        console.log('✓ Icons initialized successfully');
    }

    // Re-initialize icons when content changes (for dynamic content)
    function observeContentChanges() {
        if (typeof MutationObserver === 'undefined') return;

        const observer = new MutationObserver((mutations) => {
            let shouldReinitialize = false;

            mutations.forEach((mutation) => {
                if (mutation.type === 'childList' && mutation.addedNodes.length > 0) {
                    // Check if any added nodes have icon placeholders
                    mutation.addedNodes.forEach(node => {
                        if (node.nodeType === Node.ELEMENT_NODE) {
                            if (node.querySelector && (
                                node.querySelector('.btn-icon-left') ||
                                node.querySelector('.stat-icon') ||
                                node.querySelector('.vote-icon') ||
                                node.classList?.contains('btn-icon-left')
                            )) {
                                shouldReinitialize = true;
                            }
                        }
                    });
                }
            });

            if (shouldReinitialize) {
                setTimeout(initIcons, 50); // Debounce re-initialization
            }
        });

        // Observe the main content area for changes
        const contentArea = document.querySelector('.content');
        if (contentArea) {
            observer.observe(contentArea, {
                childList: true,
                subtree: true
            });
        }
    }

    // Initialize when DOM is ready
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', () => {
            initIcons();
            observeContentChanges();
        });
    } else {
        initIcons();
        observeContentChanges();
    }

    // Export reinit function for manual calls
    window.reinitializeIcons = initIcons;
})();

webapp/static/styles-new.css.content:
/* ========================================
   VOUCH PORTAL - MODERN PROFESSIONAL STYLES
   ======================================== */

/* ========================================
   1. CSS VARIABLES & DESIGN TOKENS
   ======================================== */
:root {
    /* Color Palette - Dark Theme */
    --bg-primary: #0a0e14;
    --bg-secondary: #151b24;
    --bg-tertiary: #1e2632;
    --bg-card: #1a2332;
    --bg-card-hover: #212d3f;

    /* Accent Colors */
    --accent-blue: #2AABEE;
    --accent-blue-hover: #1e98d4;
    --accent-blue-light: rgba(42, 171, 238, 0.1);
    --accent-green: #4CAF50;
    --accent-green-light: rgba(76, 175, 80, 0.1);
    --accent-amber: #FFB300;
    --accent-amber-light: rgba(255, 179, 0, 0.1);
    --accent-red: #F44336;
    --accent-red-light: rgba(244, 67, 54, 0.1);

    /* Text Colors */
    --text-primary: #E8EAED;
    --text-secondary: #9AA0A6;
    --text-tertiary: #6B7280;
    --text-link: var(--accent-blue);

    /* Border & Divider */
    --border-color: #2a3441;
    --border-color-light: #3a4451;
    --divider-color: rgba(255, 255, 255, 0.08);

    /* Shadows - Layered approach */
    --shadow-sm: 0 1px 2px 0 rgba(0, 0, 0, 0.3);
    --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.4), 0 2px 4px -1px rgba(0, 0, 0, 0.3);
    --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.4), 0 4px 6px -2px rgba(0, 0, 0, 0.3);
    --shadow-xl: 0 20px 25px -5px rgba(0, 0, 0, 0.5), 0 10px 10px -5px rgba(0, 0, 0, 0.3);

    /* Spacing Scale - 8px grid */
    --space-1: 0.25rem;  /* 4px */
    --space-2: 0.5rem;   /* 8px */
    --space-3: 0.75rem;  /* 12px */
    --space-4: 1rem;     /* 16px */
    --space-5: 1.25rem;  /* 20px */
    --space-6: 1.5rem;   /* 24px */
    --space-8: 2rem;     /* 32px */
    --space-10: 2.5rem;  /* 40px */
    --space-12: 3rem;    /* 48px */

    /* Typography Scale */
    --text-xs: 0.75rem;   /* 12px */
    --text-sm: 0.875rem;  /* 14px */
    --text-base: 1rem;    /* 16px */
    --text-lg: 1.125rem;  /* 18px */
    --text-xl: 1.25rem;   /* 20px */
    --text-2xl: 1.5rem;   /* 24px */
    --text-3xl: 1.875rem; /* 30px */

    /* Border Radius */
    --radius-sm: 0.375rem;  /* 6px */
    --radius-md: 0.5rem;    /* 8px */
    --radius-lg: 0.75rem;   /* 12px */
    --radius-xl: 1rem;      /* 16px */
    --radius-full: 9999px;

    /* Transitions */
    --transition-fast: 150ms cubic-bezier(0.4, 0, 0.2, 1);
    --transition-base: 200ms cubic-bezier(0.4, 0, 0.2, 1);
    --transition-slow: 300ms cubic-bezier(0.4, 0, 0.2, 1);
    --transition-bounce: 500ms cubic-bezier(0.68, -0.55, 0.265, 1.55);

    /* Z-index Scale */
    --z-base: 1;
    --z-dropdown: 100;
    --z-sticky: 200;
    --z-modal-backdrop: 1000;
    --z-modal: 1001;
    --z-toast: 1100;
}

/* ========================================
   2. RESET & BASE STYLES
   ======================================== */
*, *::before, *::after {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

html {
    scroll-behavior: smooth; /* Smooth scrolling like modern apps */
}

body {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Roboto', 'Helvetica Neue', 'Arial', sans-serif;
    background-color: var(--bg-primary);
    color: var(--text-primary);
    line-height: 1.6;
    font-size: var(--text-base);
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
    overflow-x: hidden;
    -webkit-tap-highlight-color: transparent; /* Remove tap highlight on mobile */
}

/* Improve text rendering */
h1, h2, h3, h4, h5, h6 {
    font-weight: 600;
    line-height: 1.3;
    color: var(--text-primary);
}

a {
    color: var(--text-link);
    text-decoration: none;
    transition: color var(--transition-fast);
}

a:hover {
    color: var(--accent-blue-hover);
}

/* ========================================
   3. LAYOUT & STRUCTURE
   ======================================== */
#app {
    max-width: 100%;
    min-height: 100vh;
    display: flex;
    flex-direction: column;
}

/* Header */
.header {
    background: var(--bg-secondary);
    padding: var(--space-4);
    display: flex;
    justify-content: space-between;
    align-items: center;
    border-bottom: 1px solid var(--border-color);
    position: sticky;
    top: 0;
    z-index: var(--z-sticky);
    backdrop-filter: blur(10px);
    background: rgba(21, 27, 36, 0.95);
}

.header h1 {
    font-size: var(--text-xl);
    font-weight: 700;
    background: linear-gradient(135deg, var(--accent-blue) 0%, #52C1FF 100%);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
}

.user-badge {
    font-size: var(--text-sm);
    padding: var(--space-2) var(--space-4);
    background: var(--bg-card);
    border-radius: var(--radius-full);
    border: 1px solid var(--border-color);
    font-weight: 500;
    color: var(--text-secondary);
}

/* Global Search Bar */
.header-search {
    flex: 1;
    max-width: 400px;
    margin: 0 var(--space-4);
    position: relative;
}

.search-icon-header {
    position: absolute;
    left: var(--space-3);
    top: 50%;
    transform: translateY(-50%);
    width: 16px;
    height: 16px;
    opacity: 0.5;
    pointer-events: none;
}

.search-icon-header::before {
    content: '🔍';
    font-size: var(--text-sm);
}

.global-search-input {
    width: 100%;
    padding: var(--space-2) var(--space-3) var(--space-2) var(--space-8);
    background: var(--bg-tertiary);
    border: 2px solid var(--border-color);
    border-radius: var(--radius-full);
    color: var(--text-primary);
    font-size: var(--text-sm);
    font-weight: 500;
    transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
    outline: none;
}

.global-search-input:focus {
    border-color: var(--accent-blue);
    background: var(--bg-card);
    box-shadow: 0 0 0 4px rgba(42, 171, 238, 0.15), 0 2px 8px rgba(0, 0, 0, 0.1);
    transform: translateY(-1px);
}

.global-search-input:hover:not(:focus) {
    border-color: var(--border-color-light);
    background: var(--bg-card);
}

.global-search-input::placeholder {
    color: var(--text-tertiary);
}

/* Search Results Dropdown */
.search-results-dropdown {
    position: absolute;
    top: calc(100% + var(--space-2));
    left: 0;
    right: 0;
    background: var(--bg-card);
    border: 1px solid var(--border-color);
    border-radius: var(--radius-lg);
    box-shadow: var(--shadow-xl);
    max-height: 400px;
    overflow-y: auto;
    z-index: var(--z-dropdown);
    display: none;
}

.search-results-dropdown.show {
    display: block;
    animation: fadeIn 0.2s ease-out;
}

.search-result-item {
    padding: var(--space-3);
    border-bottom: 1px solid var(--border-color);
    cursor: pointer;
    transition: background var(--transition-fast);
    display: flex;
    align-items: center;
    gap: var(--space-3);
}

.search-result-item:last-child {
    border-bottom: none;
}

.search-result-item:hover {
    background: var(--bg-card-hover);
}

.search-result-avatar {
    width: 36px;
    height: 36px;
    border-radius: var(--radius-full);
    background: var(--bg-tertiary);
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: var(--text-lg);
}

.search-result-info {
    flex: 1;
}

.search-result-name {
    font-weight: 500;
    color: var(--text-primary);
    font-size: var(--text-sm);
}

.search-result-rank {
    font-size: var(--text-xs);
    color: var(--text-secondary);
}

.search-empty {
    padding: var(--space-6);
    text-align: center;
    color: var(--text-secondary);
    font-size: var(--text-sm);
}

@keyframes fadeIn {
    from {
        opacity: 0;
        transform: translateY(-10px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}

/* Responsive adjustments for header search */
@media (max-width: 640px) {
    .header {
        flex-wrap: wrap;
    }

    .header-search {
        order: 3;
        margin-top: var(--space-3);
        max-width: 100%;
        flex-basis: 100%;
    }
}

/* Navigation Tabs - Twitter-inspired with better spacing */
.tabs {
    display: flex;
    background: var(--bg-secondary);
    border-bottom: 1px solid var(--border-color);
    overflow-x: auto;
    position: sticky;
    top: 73px;
    z-index: calc(var(--z-sticky) - 1);
    scrollbar-width: none; /* Firefox */
    gap: var(--space-2); /* Add gap between tabs */
}

.tabs::-webkit-scrollbar {
    display: none; /* Chrome, Safari */
}

.tab-btn {
    flex: 1;
    min-width: max-content; /* Better than fit-content for long words */
    max-width: 140px; /* Prevent tabs from getting too wide */
    padding: var(--space-3) var(--space-4); /* Slightly tighter vertical padding */
    background: transparent;
    border: none;
    color: var(--text-secondary);
    font-size: var(--text-sm);
    font-weight: 600; /* Slightly bolder */
    cursor: pointer;
    transition: all var(--transition-base);
    border-bottom: 2px solid transparent;
    white-space: nowrap;
    position: relative;
    overflow: hidden;
    text-overflow: ellipsis;
}

.tab-btn::after {
    content: '';
    position: absolute;
    bottom: -2px;
    left: 0;
    right: 0;
    height: 2px;
    background: var(--accent-blue);
    transform: scaleX(0);
    transition: transform var(--transition-base);
}

.tab-btn:hover {
    color: var(--text-primary);
    background: rgba(255, 255, 255, 0.03);
}

.tab-btn.active {
    color: var(--accent-blue);
}

.tab-btn.active::after {
    transform: scaleX(1);
}

/* Content Area - Better spacing like Twitter feed */
.content {
    flex: 1;
    padding: var(--space-5) var(--space-4); /* More vertical breathing room */
    max-width: 680px; /* Slightly narrower for better readability */
    margin: 0 auto;
    width: 100%;
}

.tab-content {
    display: none;
    animation: fadeInUp 0.3s ease-out;
}

.tab-content.active {
    display: block;
}

/* Section spacing */
.section {
    margin-bottom: var(--space-6); /* Consistent section spacing */
}

.section h3 {
    margin-bottom: var(--space-4);
    font-size: var(--text-lg);
    font-weight: 700;
    letter-spacing: -0.02em; /* Tighter kerning for modern look */
}

@keyframes fadeInUp {
    from {
        opacity: 0;
        transform: translateY(20px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}

@keyframes fadeIn {
    from {
        opacity: 0;
    }
    to {
        opacity: 1;
    }
}

/* Add fade-in to all cards on load */
.profile-card,
.vouch-form-card,
.community-card,
.stat-card,
.vouch-item {
    animation: fadeInUp 0.4s ease-out backwards;
}

/* Stagger animation for grid items */
.community-card:nth-child(1) { animation-delay: 0.05s; }
.community-card:nth-child(2) { animation-delay: 0.1s; }
.community-card:nth-child(3) { animation-delay: 0.15s; }
.community-card:nth-child(4) { animation-delay: 0.2s; }
.community-card:nth-child(5) { animation-delay: 0.25s; }
.community-card:nth-child(6) { animation-delay: 0.3s; }

.stat-card:nth-child(1) { animation-delay: 0.05s; }
.stat-card:nth-child(2) { animation-delay: 0.1s; }
.stat-card:nth-child(3) { animation-delay: 0.15s; }

.vouch-item:nth-child(1) { animation-delay: 0.05s; }
.vouch-item:nth-child(2) { animation-delay: 0.1s; }
.vouch-item:nth-child(3) { animation-delay: 0.15s; }
.vouch-item:nth-child(4) { animation-delay: 0.2s; }
.vouch-item:nth-child(5) { animation-delay: 0.25s; }

/* ========================================
   4. CARD COMPONENTS - Elevated design system
   ======================================== */
.profile-card,
.vouch-form-card {
    background: var(--bg-card);
    border-radius: var(--radius-xl); /* Larger radius like modern apps */
    padding: var(--space-6);
    margin-bottom: var(--space-5);
    box-shadow: var(--shadow-md);
    border: 1px solid var(--border-color);
    transition: all var(--transition-base);
}

.profile-card:hover,
.vouch-form-card:hover {
    border-color: var(--border-color-light);
    box-shadow: var(--shadow-lg); /* Lift on hover */
}

.profile-card:hover {
    box-shadow: var(--shadow-lg);
}

/* Profile Header */
.profile-header {
    display: flex;
    align-items: flex-start;
    gap: var(--space-4);
    margin-bottom: var(--space-6);
    position: relative;
}

.avatar {
    width: 64px;
    height: 64px;
    border-radius: var(--radius-full);
    background: var(--bg-secondary);
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: var(--text-2xl);
    border: 2px solid var(--accent-blue);
    flex-shrink: 0;
    position: relative;
    overflow: hidden;
}

.avatar::after {
    content: '';
    position: absolute;
    inset: 0;
    border-radius: var(--radius-full);
    background: linear-gradient(135deg, transparent 0%, rgba(42, 171, 238, 0.1) 100%);
    pointer-events: none;
}

.profile-info {
    flex: 1;
    min-width: 0; /* Allow text truncation */
}

.profile-info h2 {
    font-size: var(--text-xl);
    margin-bottom: var(--space-2);
    color: var(--text-primary);
}

/* Icon Button */
.btn-icon {
    background: var(--bg-secondary);
    border: 1px solid var(--border-color);
    border-radius: var(--radius-full);
    width: 40px;
    height: 40px;
    display: flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
    font-size: var(--text-base);
    transition: all var(--transition-base);
    color: var(--text-secondary);
    flex-shrink: 0;
}

.btn-icon:hover {
    background: var(--accent-blue);
    border-color: var(--accent-blue);
    color: white;
    transform: scale(1.05);
}

.btn-icon:active {
    transform: scale(0.95);
}

/* Profile Bio & Location */
.profile-bio {
    margin-bottom: var(--space-4);
    padding: var(--space-4);
    background: var(--bg-secondary);
    border-radius: var(--radius-md);
    border-left: 3px solid var(--accent-blue);
    font-size: var(--text-sm);
    line-height: 1.6;
    color: var(--text-secondary);
}

.profile-location {
    display: flex;
    align-items: center;
    gap: var(--space-2);
    margin-bottom: var(--space-4);
    font-size: var(--text-sm);
    color: var(--text-secondary);
}

.location-icon {
    width: 16px;
    height: 16px;
    color: var(--accent-blue);
}

/* ========================================
   5. STATS & METRICS
   ======================================== */
.stats-grid {
    display: grid;
    grid-template-columns: repeat(3, 1fr); /* Always 3 columns for consistency */
    gap: var(--space-3); /* Tighter gap */
    margin-bottom: var(--space-6);
}

.stat-card {
    background: var(--bg-secondary);
    padding: var(--space-4) var(--space-3); /* More compact */
    border-radius: var(--radius-xl); /* Larger radius */
    text-align: center;
    border: 1px solid var(--border-color);
    transition: all var(--transition-base);
    position: relative;
    overflow: hidden;
    cursor: pointer; /* Make it feel interactive */
}

/* Add subtle gradient overlay */
.stat-card::after {
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background: linear-gradient(135deg, rgba(42, 171, 238, 0.05) 0%, transparent 100%);
    opacity: 0;
    transition: opacity var(--transition-base);
}

.stat-card::before {
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    width: 4px;
    height: 100%;
    background: var(--accent-blue);
    transform: scaleY(0);
    transition: transform var(--transition-base);
}

.stat-card:hover {
    transform: translateY(-3px) scale(1.02); /* Lift and slight grow */
    box-shadow: var(--shadow-lg);
    border-color: var(--border-color-light);
}

.stat-card:hover::before {
    transform: scaleY(1);
}

.stat-card:hover::after {
    opacity: 1;
}

.stat-card:active {
    transform: translateY(-1px) scale(1);
}

.stat-icon {
    width: 24px;
    height: 24px;
    margin: 0 auto var(--space-2);
    color: var(--accent-blue);
}

.stat-value {
    font-size: 2rem; /* 32px - Slightly smaller for balance */
    font-weight: 800; /* Extra bold */
    color: var(--accent-blue);
    line-height: 1;
    margin-bottom: var(--space-2);
    font-variant-numeric: tabular-nums; /* Align numbers nicely */
    position: relative;
    z-index: 1;
}

.stat-label {
    font-size: 10px; /* Smaller, more subtle */
    color: var(--text-tertiary);
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.8px;
    position: relative;
    z-index: 1;
}

/* Stat Card Variants */
.stat-card.positive-votes .stat-value {
    color: var(--accent-green);
}

.stat-card.positive-votes::before {
    background: var(--accent-green);
}

.stat-card.negative-votes .stat-value {
    color: var(--accent-red);
}

.stat-card.negative-votes::before {
    background: var(--accent-red);
}

.stat-card.streak-card .stat-value {
    color: var(--accent-amber);
}

.stat-card.streak-card::before {
    background: var(--accent-amber);
}

.stat-card.active-streak {
    background: var(--accent-amber-light);
    border-color: var(--accent-amber);
}

/* ========================================
   6. PROGRESS BAR
   ======================================== */
.progress-section {
    margin-bottom: var(--space-6);
}

.progress-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: var(--space-3);
    font-size: var(--text-sm);
    color: var(--text-secondary);
    font-weight: 500;
}

.progress-bar {
    height: 8px;
    background: var(--bg-secondary);
    border-radius: var(--radius-full);
    overflow: hidden;
    position: relative;
}

.progress-fill {
    height: 100%;
    background: linear-gradient(90deg, var(--accent-blue), var(--accent-green));
    transition: width 0.5s cubic-bezier(0.4, 0, 0.2, 1);
    border-radius: var(--radius-full);
    position: relative;
    overflow: hidden;
}

.progress-fill::after {
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    bottom: 0;
    right: 0;
    background: linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.2), transparent);
    animation: shimmer 2s infinite;
}

/* Pulse animation for call-to-action elements */
@keyframes pulse {
    0%, 100% {
        box-shadow: 0 0 0 0 rgba(42, 171, 238, 0.7);
    }
    50% {
        box-shadow: 0 0 0 8px rgba(42, 171, 238, 0);
    }
}

.btn-primary.pulse {
    animation: pulse 2s infinite;
}

@keyframes shimmer {
    0% {
        transform: translateX(-100%);
    }
    100% {
        transform: translateX(100%);
    }
}

/* ========================================
   7. BUTTONS
   ======================================== */
.btn {
    padding: var(--space-3) var(--space-6);
    border: none;
    border-radius: var(--radius-full); /* Full rounded like Twitter */
    font-size: var(--text-base);
    font-weight: 700; /* Bolder for better hierarchy */
    cursor: pointer;
    transition: all var(--transition-base);
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: var(--space-2);
    position: relative;
    overflow: hidden;
    font-family: inherit;
    min-height: 44px; /* Better touch target (44px is Apple's recommended minimum) */
    letter-spacing: -0.01em;
}

.btn::before {
    content: '';
    position: absolute;
    top: 50%;
    left: 50%;
    width: 0;
    height: 0;
    border-radius: var(--radius-full);
    background: rgba(255, 255, 255, 0.1);
    transform: translate(-50%, -50%);
    transition: width 0.6s, height 0.6s;
}

.btn:active::before {
    width: 300px;
    height: 300px;
}

.btn-primary {
    background: var(--accent-blue);
    color: white;
    box-shadow: var(--shadow-sm);
}

.btn-primary:hover {
    background: var(--accent-blue-hover);
    transform: translateY(-1px);
    box-shadow: var(--shadow-md);
}

.btn-primary:active {
    transform: translateY(0);
}

.btn-secondary {
    background: var(--bg-secondary);
    color: var(--text-primary);
    border: 1px solid var(--border-color);
}

.btn-secondary:hover {
    background: var(--bg-tertiary);
    border-color: var(--border-color-light);
}

.btn-large {
    width: 100%;
    padding: var(--space-4) var(--space-6);
    font-size: var(--text-lg);
}

.btn-small {
    padding: var(--space-2) var(--space-4);
    font-size: var(--text-sm);
}

.btn:disabled {
    opacity: 0.5;
    cursor: not-allowed;
    transform: none !important;
}

.btn-icon-left {
    width: 20px;
    height: 20px;
}

/* Action Buttons */
.action-buttons {
    display: flex;
    gap: var(--space-3);
    flex-wrap: wrap;
}

.action-buttons .btn {
    flex: 1;
    min-width: 140px;
}

/* Pulse Animation for Special Buttons */
@keyframes pulse-ring {
    0% {
        box-shadow: 0 0 0 0 rgba(42, 171, 238, 0.7);
    }
    50% {
        box-shadow: 0 0 0 10px rgba(42, 171, 238, 0);
    }
    100% {
        box-shadow: 0 0 0 0 rgba(42, 171, 238, 0);
    }
}

.pulse {
    animation: pulse-ring 2s cubic-bezier(0.4, 0, 0.6, 1) infinite;
}

/* ========================================
   8. RANK BADGES
   ======================================== */
.rank-badge, .rank-badge-large {
    display: inline-flex;
    align-items: center;
    gap: var(--space-2);
    padding: var(--space-2) var(--space-4);
    border-radius: var(--radius-full);
    font-size: var(--text-sm);
    font-weight: 700;
    border: 2px solid var(--border-color);
    transition: all var(--transition-base);
    position: relative;
    overflow: hidden;
}

.rank-badge:hover, .rank-badge-large:hover {
    transform: scale(1.05);
    box-shadow: var(--shadow-md);
}

/* Shine effect on rank badges */
.rank-badge::after, .rank-badge-large::after {
    content: '';
    position: absolute;
    top: -50%;
    left: -50%;
    width: 200%;
    height: 200%;
    background: linear-gradient(
        45deg,
        transparent,
        rgba(255, 255, 255, 0.1),
        transparent
    );
    transform: translateX(-100%) translateY(-100%) rotate(45deg);
    transition: transform 0.6s;
}

.rank-badge:hover::after, .rank-badge-large:hover::after {
    transform: translateX(100%) translateY(100%) rotate(45deg);
}

.rank-badge-large {
    padding: var(--space-3) var(--space-6);
    font-size: var(--text-lg);
    margin: var(--space-2) 0;
    font-weight: 800;
}

/* Rank Color Variants */
.rank-badge.unverified, .rank-badge-large.unverified {
    background: rgba(158, 158, 158, 0.1);
    border-color: #9E9E9E;
    color: #9E9E9E;
}

.rank-badge.verified, .rank-badge-large.verified {
    background: var(--accent-green-light);
    border-color: var(--accent-green);
    color: var(--accent-green);
}

.rank-badge.trusted, .rank-badge-large.trusted {
    background: var(--accent-blue-light);
    border-color: var(--accent-blue);
    color: var(--accent-blue);
}

.rank-badge.endorsed, .rank-badge-large.endorsed {
    background: rgba(255, 152, 0, 0.1);
    border-color: #FF9800;
    color: #FF9800;
}

.rank-badge.top_tier, .rank-badge-large.top_tier {
    background: linear-gradient(135deg, rgba(255, 215, 0, 0.2), rgba(255, 193, 7, 0.2));
    border-color: #FFD700;
    color: #FFD700;
    box-shadow: 0 0 20px rgba(255, 215, 0, 0.3);
    animation: glow 2s ease-in-out infinite alternate;
}

@keyframes glow {
    from {
        box-shadow: 0 0 10px rgba(255, 215, 0, 0.3);
    }
    to {
        box-shadow: 0 0 20px rgba(255, 215, 0, 0.6), 0 0 30px rgba(255, 215, 0, 0.3);
    }
}

/* Rating Display */
.rating-display {
    margin-top: var(--space-4);
    text-align: center;
    padding: var(--space-6);
    border-radius: var(--radius-lg);
    border: 2px solid var(--accent-green);
    background: var(--accent-green-light);
}

.rating-percentage {
    font-size: 3rem;
    font-weight: 700;
    line-height: 1;
    margin-bottom: var(--space-2);
    background: linear-gradient(135deg, var(--accent-green) 0%, #66BB6A 100%);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
}

.rating-label {
    font-size: var(--text-sm);
    color: var(--text-secondary);
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 600;
}

.rating-display.rating-medium {
    border-color: var(--accent-amber);
    background: var(--accent-amber-light);
}

.rating-display.rating-medium .rating-percentage {
    background: linear-gradient(135deg, var(--accent-amber) 0%, #FFC107 100%);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
}

.rating-display.rating-low {
    border-color: var(--accent-red);
    background: var(--accent-red-light);
}

.rating-display.rating-low .rating-percentage {
    background: linear-gradient(135deg, var(--accent-red) 0%, #E57373 100%);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
}

/* ========================================
   9. FORMS
   ======================================== */
.form-group {
    margin-bottom: var(--space-5);
}

.form-group label {
    display: block;
    margin-bottom: var(--space-2);
    font-weight: 500;
    font-size: var(--text-sm);
    color: var(--text-primary);
}

.form-group input,
.form-group textarea {
    width: 100%;
    padding: var(--space-4); /* More padding for better feel */
    background: var(--bg-secondary);
    border: 2px solid var(--border-color); /* Thicker border */
    border-radius: var(--radius-lg); /* Larger radius */
    color: var(--text-primary);
    font-size: var(--text-base);
    font-family: inherit;
    transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}

.form-group input:focus,
.form-group textarea:focus {
    outline: none;
    border-color: var(--accent-blue);
    box-shadow: 0 0 0 4px var(--accent-blue-light), 0 2px 8px rgba(0, 0, 0, 0.1);
    background: var(--bg-card);
    transform: translateY(-1px); /* Subtle lift */
}

.form-group textarea {
    resize: vertical;
    min-height: 100px;
}

.char-count {
    text-align: right;
    font-size: var(--text-xs);
    color: var(--text-tertiary);
    margin-top: var(--space-1);
}

/* Search Input */
.search-input-wrapper {
    position: relative;
    flex: 1;
}

.search-icon {
    position: absolute;
    left: var(--space-4);
    top: 50%;
    transform: translateY(-50%);
    width: 20px;
    height: 20px;
    color: var(--text-tertiary);
    pointer-events: none;
}

.search-input {
    width: 100%;
    padding: var(--space-3) var(--space-4) var(--space-3) var(--space-10);
    background: var(--bg-card);
    border: 1px solid var(--border-color);
    border-radius: var(--radius-md);
    color: var(--text-primary);
    font-size: var(--text-base);
    transition: all var(--transition-base);
}

.search-input:focus {
    outline: none;
    border-color: var(--accent-blue);
    box-shadow: 0 0 0 3px var(--accent-blue-light);
}

/* Vote Buttons */
.vote-buttons {
    display: flex;
    gap: var(--space-4);
}

.vote-btn {
    flex: 1;
    padding: var(--space-5);
    border: 2px solid var(--border-color);
    background: var(--bg-card);
    color: var(--text-primary);
    font-size: var(--text-lg);
    font-weight: 600;
    border-radius: var(--radius-lg);
    cursor: pointer;
    transition: all var(--transition-base);
    display: flex;
    align-items: center;
    justify-content: center;
    gap: var(--space-2);
}

.vote-btn .vote-icon {
    width: 24px;
    height: 24px;
}

.vote-btn:hover {
    transform: translateY(-2px);
    box-shadow: var(--shadow-md);
}

.vote-btn.vote-positive {
    border-color: var(--accent-green);
}

.vote-btn.vote-positive.active {
    background: var(--accent-green);
    color: white;
    box-shadow: 0 4px 12px rgba(76, 175, 80, 0.3);
}

.vote-btn.vote-negative {
    border-color: var(--accent-red);
}

.vote-btn.vote-negative.active {
    background: var(--accent-red);
    color: white;
    box-shadow: 0 4px 12px rgba(244, 67, 54, 0.3);
}

/* Disclaimer */
.disclaimer {
    display: flex;
    gap: var(--space-3);
    background: var(--accent-amber-light);
    border-left: 3px solid var(--accent-amber);
    padding: var(--space-4);
    margin-bottom: var(--space-5);
    font-size: var(--text-sm);
    color: var(--text-secondary);
    border-radius: var(--radius-md);
    line-height: 1.6;
}

.disclaimer-icon {
    width: 20px;
    height: 20px;
    color: var(--accent-amber);
    flex-shrink: 0;
}

/* ========================================
   10. SECTIONS & LISTS
   ======================================== */
.section {
    margin-bottom: var(--space-8);
}

.section h3 {
    font-size: var(--text-xl);
    margin-bottom: var(--space-4);
    color: var(--text-primary);
    font-weight: 600;
}

.section h4 {
    font-size: var(--text-lg);
    margin-bottom: var(--space-3);
    color: var(--text-secondary);
    font-weight: 500;
}

/* Vouch Lists */
.vouch-list,
.mini-vouch-list {
    display: flex;
    flex-direction: column;
    gap: var(--space-3);
}

.vouch-item {
    background: var(--bg-card);
    padding: var(--space-4);
    border-radius: var(--radius-lg); /* Slightly larger radius */
    border: 1px solid var(--border-color);
    transition: all var(--transition-base);
    position: relative;
}

/* Add subtle left accent bar on hover */
.vouch-item::before {
    content: '';
    position: absolute;
    left: 0;
    top: 0;
    bottom: 0;
    width: 3px;
    background: var(--accent-blue);
    border-radius: var(--radius-lg) 0 0 var(--radius-lg);
    transform: scaleY(0);
    transition: transform var(--transition-base);
}

.vouch-item:hover {
    border-color: var(--border-color-light);
    transform: translateX(2px); /* Subtle slide */
    box-shadow: var(--shadow-sm);
}

.vouch-item:hover::before {
    transform: scaleY(1);
}

.vouch-item.pending {
    opacity: 0.7;
    border-left: 3px solid var(--accent-blue);
}

.vouch-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: var(--space-2);
}

.vouch-user {
    font-weight: 600;
    color: var(--accent-blue);
    font-size: var(--text-base);
}

.vouch-date {
    font-size: var(--text-xs);
    color: var(--text-tertiary);
}

.vouch-message {
    color: var(--text-secondary);
    font-size: var(--text-sm);
    line-height: 1.6;
    font-style: italic;
    padding: var(--space-3);
    background: rgba(255, 255, 255, 0.02);
    border-radius: var(--radius-sm);
    margin-top: var(--space-2);
}

.vouch-actions {
    margin-top: var(--space-3);
    display: flex;
    gap: var(--space-2);
}

.btn-edit,
.btn-delete {
    padding: var(--space-2) var(--space-4);
    background: var(--bg-secondary);
    border: 1px solid var(--border-color);
    border-radius: var(--radius-md);
    color: var(--text-primary);
    font-size: var(--text-sm);
    cursor: pointer;
    transition: all var(--transition-base);
    display: inline-flex;
    align-items: center;
    gap: var(--space-2);
    flex: 1;
    justify-content: center;
}

.btn-edit:hover {
    background: var(--bg-tertiary);
    border-color: var(--accent-blue);
    transform: translateY(-1px);
}

.btn-delete {
    border-color: var(--accent-red-light);
    color: var(--accent-red);
}

.btn-delete:hover {
    background: var(--accent-red-light);
    border-color: var(--accent-red);
    transform: translateY(-1px);
}

.empty-state {
    text-align: center;
    padding: var(--space-12) var(--space-6);
    color: var(--text-secondary);
    font-size: var(--text-base);
    background: var(--bg-secondary);
    border-radius: var(--radius-xl);
    border: 2px dashed var(--border-color);
    margin: var(--space-4) 0;
}

.empty-state::before {
    content: '📭';
    display: block;
    font-size: 48px;
    margin-bottom: var(--space-4);
    opacity: 0.5;
    animation: float 3s ease-in-out infinite;
}

@keyframes float {
    0%, 100% {
        transform: translateY(0px);
    }
    50% {
        transform: translateY(-10px);
    }
}

/* Recent Vouches */
.recent-vouches {
    margin-top: var(--space-8);
    padding-top: var(--space-6);
    border-top: 1px solid var(--divider-color);
}

/* ========================================
   11. COMMUNITY COMPONENTS
   ======================================== */
.community-view-tabs {
    display: flex;
    gap: var(--space-2);
    margin-bottom: var(--space-4);
    background: var(--bg-secondary);
    padding: var(--space-2);
    border-radius: var(--radius-lg);
}

.view-tab-btn {
    flex: 1;
    padding: var(--space-3) var(--space-4);
    background: transparent;
    border: none;
    color: var(--text-secondary);
    font-size: var(--text-sm);
    font-weight: 500;
    cursor: pointer;
    border-radius: var(--radius-md);
    transition: all var(--transition-base);
    display: flex;
    align-items: center;
    justify-content: center;
    gap: var(--space-2);
}

.view-tab-btn .tab-icon {
    width: 18px;
    height: 18px;
}

.view-tab-btn:hover {
    background: rgba(255, 255, 255, 0.05);
}

.view-tab-btn.active {
    background: var(--accent-blue);
    color: white;
}

.community-view {
    display: none;
}

.community-view.active {
    display: block;
}

/* Search Section */
.search-section {
    margin-bottom: var(--space-4);
}

/* Filters */
.filters {
    display: flex;
    gap: var(--space-2);
    margin-bottom: var(--space-6);
    overflow-x: auto;
    padding-bottom: var(--space-2);
    scrollbar-width: none;
}

.filters::-webkit-scrollbar {
    display: none;
}

.filter-btn {
    padding: var(--space-2) var(--space-4);
    background: var(--bg-card);
    border: 1px solid var(--border-color);
    border-radius: var(--radius-full);
    color: var(--text-secondary);
    font-size: var(--text-sm);
    font-weight: 500;
    cursor: pointer;
    white-space: nowrap;
    transition: all var(--transition-base);
    display: inline-flex;
    align-items: center;
    gap: var(--space-2);
}

.filter-btn .filter-icon {
    width: 16px;
    height: 16px;
}

.filter-btn:hover {
    border-color: var(--border-color-light);
    background: var(--bg-tertiary);
}

.filter-btn.active {
    background: var(--accent-blue);
    color: white;
    border-color: var(--accent-blue);
}

/* Community Grid */
.community-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(150px, 1fr));
    gap: var(--space-4);
}

.community-card {
    background: var(--bg-card);
    padding: var(--space-5);
    border-radius: var(--radius-xl); /* Larger radius */
    text-align: center;
    cursor: pointer;
    transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1); /* Smooth easing */
    border: 1px solid var(--border-color);
    position: relative;
    overflow: hidden;
}

/* Add gradient overlay on hover */
.community-card::before {
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background: linear-gradient(135deg, rgba(42, 171, 238, 0.1) 0%, transparent 100%);
    opacity: 0;
    transition: opacity var(--transition-base);
}

.community-card:hover {
    transform: translateY(-6px) scale(1.02); /* Lift and grow */
    box-shadow: var(--shadow-xl);
    border-color: var(--accent-blue);
}

.community-card:hover::before {
    opacity: 1;
}

.community-card:active {
    transform: translateY(-3px) scale(1);
}

.community-avatar {
    width: 56px; /* Slightly larger */
    height: 56px;
    border-radius: var(--radius-full);
    background: var(--bg-secondary);
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: var(--text-xl);
    margin: 0 auto var(--space-3);
    border: 3px solid var(--border-color);
    transition: all var(--transition-base);
    position: relative;
    z-index: 1;
}

.community-card:hover .community-avatar {
    border-color: var(--accent-blue);
    transform: scale(1.1);
    box-shadow: 0 4px 12px rgba(42, 171, 238, 0.3);
}

.community-name {
    font-weight: 600;
    margin-bottom: var(--space-1);
    font-size: var(--text-base);
    color: var(--text-primary);
}

.community-rank {
    font-size: var(--text-xs);
    margin-bottom: var(--space-1);
    color: var(--text-secondary);
}

.community-vouches {
    font-size: var(--text-xs);
    color: var(--text-tertiary);
}

/* Activity Feed */
.activity-feed {
    display: flex;
    flex-direction: column;
    gap: var(--space-3);
}

.activity-item {
    background: var(--bg-card);
    border-radius: var(--radius-md);
    padding: var(--space-4);
    display: flex;
    gap: var(--space-4);
    align-items: flex-start;
    transition: all var(--transition-base);
    border: 1px solid var(--border-color);
}

.activity-item:hover {
    transform: translateX(4px);
    background: var(--bg-card-hover);
    border-color: var(--border-color-light);
}

.activity-item.rank-up {
    border-left: 3px solid var(--accent-amber);
}

.activity-icon {
    font-size: var(--text-2xl);
    flex-shrink: 0;
    width: 40px;
    height: 40px;
    display: flex;
    align-items: center;
    justify-content: center;
    background: var(--bg-secondary);
    border-radius: var(--radius-md);
}

.activity-content {
    flex: 1;
    min-width: 0;
}

.activity-text {
    color: var(--text-primary);
    margin-bottom: var(--space-1);
    font-size: var(--text-sm);
}

.activity-text strong {
    color: var(--accent-blue);
    font-weight: 600;
}

.activity-message {
    color: var(--text-secondary);
    font-style: italic;
    font-size: var(--text-sm);
    margin-top: var(--space-2);
    padding: var(--space-2);
    background: rgba(255, 255, 255, 0.02);
    border-radius: var(--radius-sm);
}

.activity-time {
    color: var(--text-tertiary);
    font-size: var(--text-xs);
    margin-top: var(--space-1);
}

/* Leaderboards */
.leaderboard-tabs {
    display: flex;
    gap: var(--space-2);
    margin-bottom: var(--space-4);
    overflow-x: auto;
    scrollbar-width: none;
}

.leaderboard-tabs::-webkit-scrollbar {
    display: none;
}

.lb-tab-btn {
    padding: var(--space-2) var(--space-3);
    background: var(--bg-card);
    border: 1px solid var(--border-color);
    color: var(--text-secondary);
    font-size: 11px; /* Smaller font for longer words */
    font-weight: 600;
    cursor: pointer;
    border-radius: var(--radius-full); /* Pills look modern */
    transition: all var(--transition-base);
    white-space: nowrap;
    flex-shrink: 0; /* Prevent shrinking */
    line-height: 1.2;
}

.lb-tab-btn:hover {
    border-color: var(--accent-blue);
    color: var(--text-primary);
    transform: translateY(-1px);
    box-shadow: var(--shadow-sm);
}

.lb-tab-btn.active {
    background: var(--accent-blue);
    color: white;
    border-color: var(--accent-blue);
    box-shadow: 0 2px 8px rgba(42, 171, 238, 0.3);
}

.leaderboard-list {
    display: flex;
    flex-direction: column;
    gap: var(--space-2);
}

.leaderboard-item {
    background: var(--bg-card);
    border-radius: var(--radius-md);
    padding: var(--space-4);
    display: flex;
    align-items: center;
    gap: var(--space-4);
    cursor: pointer;
    transition: all var(--transition-base);
    border: 1px solid var(--border-color);
}

.leaderboard-item:hover {
    background: var(--bg-card-hover);
    transform: translateX(4px);
    border-color: var(--border-color-light);
}

.lb-position {
    font-size: var(--text-xl);
    font-weight: 700;
    min-width: 2.5rem;
    text-align: center;
    color: var(--accent-amber);
}

.lb-info {
    flex: 1;
    min-width: 0;
}

.lb-name {
    font-weight: 600;
    color: var(--text-primary);
    margin-bottom: var(--space-1);
    font-size: var(--text-base);
}

.lb-stat {
    color: var(--text-secondary);
    font-size: var(--text-sm);
}

/* ========================================
   12. MODALS
   ======================================== */
.modal {
    display: none;
    position: fixed;
    z-index: var(--z-modal-backdrop);
    left: 0;
    top: 0;
    width: 100%;
    height: 100%;
    background: rgba(0, 0, 0, 0.85);
    backdrop-filter: blur(4px);
    animation: fadeIn 0.2s ease-out;
}

.modal.active {
    display: flex;
    align-items: center;
    justify-content: center;
    padding: var(--space-4);
}

.modal-content {
    background: var(--bg-card);
    padding: var(--space-8);
    border-radius: var(--radius-xl);
    max-width: 500px;
    width: 100%;
    max-height: 85vh;
    overflow-y: auto;
    position: relative;
    border: 1px solid var(--border-color);
    box-shadow: var(--shadow-xl);
    animation: slideUp 0.3s ease-out;
}

@keyframes fadeIn {
    from { opacity: 0; }
    to { opacity: 1; }
}

@keyframes slideUp {
    from {
        opacity: 0;
        transform: translateY(20px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}

.close {
    position: absolute;
    top: var(--space-4);
    right: var(--space-4);
    font-size: var(--text-2xl);
    cursor: pointer;
    color: var(--text-secondary);
    width: 32px;
    height: 32px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: var(--radius-md);
    transition: all var(--transition-base);
}

.close:hover {
    color: var(--text-primary);
    background: var(--bg-secondary);
}

.modal-content h2 {
    margin-bottom: var(--space-6);
    font-size: var(--text-2xl);
}

/* Share Modal */
.share-modal {
    max-width: 400px;
}

.share-content {
    text-align: center;
}

.share-content h2 {
    margin-bottom: var(--space-4);
}

.share-content p {
    margin-bottom: var(--space-6);
    color: var(--text-secondary);
    line-height: 1.6;
}

.share-link-container {
    display: flex;
    gap: var(--space-2);
    margin-bottom: var(--space-4);
}

.share-link-input {
    flex: 1;
    padding: var(--space-3);
    background: var(--bg-secondary);
    border: 1px solid var(--border-color);
    border-radius: var(--radius-md);
    color: var(--text-primary);
    font-size: var(--text-sm);
    font-family: 'Courier New', monospace;
}

/* ========================================
   13. TOASTS & NOTIFICATIONS
   ======================================== */
.toast {
    position: fixed;
    bottom: var(--space-8);
    left: 50%;
    transform: translateX(-50%) translateY(100px);
    background: var(--bg-card);
    color: var(--text-primary);
    padding: var(--space-4) var(--space-6);
    border-radius: var(--radius-lg);
    box-shadow: var(--shadow-xl);
    z-index: var(--z-toast);
    opacity: 0;
    transition: all var(--transition-base);
    border: 1px solid var(--border-color);
    min-width: 300px;
    text-align: center;
}

.toast.show {
    transform: translateX(-50%) translateY(0);
    opacity: 1;
}

.toast.success {
    border-left: 4px solid var(--accent-green);
}

.toast.error {
    border-left: 4px solid var(--accent-red);
}

.toast.info {
    border-left: 4px solid var(--accent-blue);
}

/* Mutual Vouch Toast */
.mutual-vouch-toast {
    position: fixed;
    bottom: -120px;
    left: 50%;
    transform: translateX(-50%);
    background: var(--bg-card);
    padding: var(--space-4);
    border-radius: var(--radius-xl);
    border: 2px solid var(--accent-blue);
    box-shadow: var(--shadow-xl);
    z-index: var(--z-toast);
    min-width: 300px;
    transition: bottom var(--transition-slow);
}

.mutual-vouch-toast.show {
    bottom: var(--space-8);
}

.mutual-vouch-content {
    display: flex;
    flex-direction: column;
    gap: var(--space-3);
    align-items: center;
}

/* ========================================
   14. LOADING STATES
   ======================================== */
.loading-overlay {
    display: none;
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background: rgba(10, 14, 20, 0.95);
    z-index: 9999;
    align-items: center;
    justify-content: center;
    backdrop-filter: blur(2px);
}

.loading-overlay.active {
    display: flex;
}

.spinner {
    width: 50px;
    height: 50px;
    border: 4px solid rgba(42, 171, 238, 0.2);
    border-top-color: var(--accent-blue);
    border-right-color: var(--accent-blue);
    border-radius: var(--radius-full);
    animation: spin 0.8s cubic-bezier(0.4, 0, 0.2, 1) infinite;
    box-shadow: 0 0 20px rgba(42, 171, 238, 0.3);
}

@keyframes spin {
    to { transform: rotate(360deg); }
}

/* Add pulsing circle behind spinner */
.spinner::before {
    content: '';
    position: absolute;
    inset: -10px;
    border-radius: var(--radius-full);
    background: radial-gradient(circle, rgba(42, 171, 238, 0.2) 0%, transparent 70%);
    animation: pulse-ring 2s ease-in-out infinite;
}

@keyframes pulse-ring {
    0%, 100% {
        transform: scale(0.95);
        opacity: 0.5;
    }
    50% {
        transform: scale(1.05);
        opacity: 0.8;
    }
}

/* Loading Skeletons */
.skeleton {
    background: linear-gradient(
        90deg,
        var(--bg-secondary) 0px,
        var(--bg-tertiary) 40px,
        var(--bg-secondary) 80px
    );
    background-size: 200% 100%;
    animation: skeleton-loading 1.5s ease-in-out infinite;
    border-radius: var(--radius-md);
}

@keyframes skeleton-loading {
    0% {
        background-position: 200% 0;
    }
    100% {
        background-position: -200% 0;
    }
}

.skeleton-text {
    height: 1rem;
    margin-bottom: var(--space-2);
}

.skeleton-text.large {
    height: 1.5rem;
}

.skeleton-text.small {
    height: 0.75rem;
}

.skeleton-circle {
    border-radius: var(--radius-full);
}

.skeleton-avatar {
    width: 64px;
    height: 64px;
    border-radius: var(--radius-full);
}

.skeleton-button {
    height: 44px;
    border-radius: var(--radius-md);
}

.skeleton-card {
    height: 120px;
    margin-bottom: var(--space-4);
}

.skeleton-stat-card {
    height: 100px;
    border-radius: var(--radius-lg);
}

/* Skeleton Layouts */
.skeleton-profile {
    padding: var(--space-6);
}

.skeleton-profile-header {
    display: flex;
    gap: var(--space-4);
    margin-bottom: var(--space-6);
}

.skeleton-profile-info {
    flex: 1;
}

.skeleton-stats-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(140px, 1fr));
    gap: var(--space-4);
    margin-bottom: var(--space-6);
}

.skeleton-vouch-list {
    display: flex;
    flex-direction: column;
    gap: var(--space-3);
}

.skeleton-vouch-item {
    background: var(--bg-card);
    padding: var(--space-4);
    border-radius: var(--radius-md);
    border: 1px solid var(--border-color);
}

.skeleton-community-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(140px, 1fr));
    gap: var(--space-3);
}

.skeleton-community-card {
    background: var(--bg-card);
    padding: var(--space-4);
    border-radius: var(--radius-lg);
    border: 1px solid var(--border-color);
    text-align: center;
}

.skeleton-community-avatar {
    width: 48px;
    height: 48px;
    border-radius: var(--radius-full);
    margin: 0 auto var(--space-3);
}

/* ========================================
   15. INSIGHTS/ANALYTICS
   ======================================== */
.insights-container h2 {
    margin-bottom: var(--space-6);
}

.stats-overview {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(140px, 1fr));
    gap: var(--space-4);
    margin-bottom: var(--space-8);
}

.insight-card {
    background: var(--bg-card);
    padding: var(--space-6);
    border-radius: var(--radius-lg);
    text-align: center;
    border: 1px solid var(--border-color);
}

.insight-value {
    font-size: var(--text-3xl);
    font-weight: 700;
    color: var(--accent-green);
}

.insight-label {
    font-size: var(--text-xs);
    color: var(--text-secondary);
    margin-top: var(--space-2);
    text-transform: uppercase;
    letter-spacing: 0.5px;
}

.rank-chart {
    display: flex;
    flex-direction: column;
    gap: var(--space-3);
}

.rank-chart-item {
    display: flex;
    align-items: center;
    gap: var(--space-4);
    padding: var(--space-3);
    background: var(--bg-card);
    border-radius: var(--radius-md);
}

.rank-chart-bar {
    flex: 1;
    height: 8px;
    background: var(--bg-secondary);
    border-radius: var(--radius-full);
    overflow: hidden;
}

.rank-chart-fill {
    height: 100%;
    background: var(--accent-blue);
    transition: width 0.5s ease;
}

.health-indicators {
    display: flex;
    flex-direction: column;
    gap: var(--space-3);
}

.health-item {
    display: flex;
    align-items: center;
    gap: var(--space-3);
    padding: var(--space-3);
    background: var(--bg-card);
    border-radius: var(--radius-md);
}

.health-status {
    font-size: var(--text-xl);
}

.status-ok {
    color: var(--accent-green);
}

.status-warning {
    color: var(--accent-amber);
}

.status-error {
    color: var(--accent-red);
}

/* ========================================
   16. FOOTER
   ======================================== */
.footer {
    background: var(--bg-secondary);
    border-top: 1px solid var(--border-color);
    padding: var(--space-6);
    text-align: center;
    margin-top: auto;
}

.footer-disclaimer {
    font-size: var(--text-sm);
    color: var(--text-tertiary);
    line-height: 1.6;
}

/* ========================================
   17. ICON STYLING
   ======================================== */
.icon {
    display: inline-flex;
    align-items: center;
    justify-content: center;
}

.icon svg {
    width: 100%;
    height: 100%;
}

/* ========================================
   18. RESPONSIVE DESIGN
   ======================================== */
@media (min-width: 768px) {
    .content {
        padding: var(--space-8);
    }

    .community-grid {
        grid-template-columns: repeat(auto-fill, minmax(160px, 1fr));
    }

    .stats-grid {
        grid-template-columns: repeat(3, 1fr);
    }
}

@media (max-width: 480px) {
    .header h1 {
        font-size: var(--text-lg);
    }

    .tab-btn {
        font-size: 11px; /* Smaller on mobile */
        padding: var(--space-3) var(--space-2);
    }

    .stats-grid {
        grid-template-columns: repeat(3, 1fr);
        gap: var(--space-2);
    }

    .stat-card {
        padding: var(--space-3) var(--space-2);
    }

    .stat-value {
        font-size: 1.5rem; /* Smaller on mobile */
    }

    .stat-label {
        font-size: 9px;
    }

    .community-grid {
        grid-template-columns: repeat(2, 1fr); /* 2 columns on small screens */
        gap: var(--space-3);
    }

    .modal-content {
        padding: var(--space-5);
    }

    .btn {
        min-height: 48px; /* Larger touch targets on mobile */
    }

    .lb-tab-btn {
        font-size: 10px;
        padding: var(--space-2);
    }

    .content {
        padding: var(--space-4) var(--space-3);
    }

    /* Make cards slightly less padded on mobile */
    .profile-card,
    .vouch-form-card {
        padding: var(--space-5);
    }
}

/* ========================================
   18. SKELETON LOADING STATES
   ======================================== */
.skeleton {
    background: linear-gradient(
        90deg,
        var(--bg-secondary) 0%,
        var(--bg-tertiary) 50%,
        var(--bg-secondary) 100%
    );
    background-size: 200% 100%;
    animation: skeleton-loading 1.5s ease-in-out infinite;
    border-radius: var(--radius-md);
}

@keyframes skeleton-loading {
    0% {
        background-position: 200% 0;
    }
    100% {
        background-position: -200% 0;
    }
}

.skeleton-card {
    height: 120px;
    margin-bottom: var(--space-4);
}

.skeleton-text {
    height: 16px;
    margin-bottom: var(--space-2);
}

.skeleton-text.short {
    width: 60%;
}

.skeleton-avatar {
    width: 56px;
    height: 56px;
    border-radius: var(--radius-full);
    margin: 0 auto var(--space-3);
}

/* ========================================
   19. UTILITY CLASSES
   ======================================== */
.text-center { text-align: center; }
.text-left { text-align: left; }
.text-right { text-align: right; }

.mt-1 { margin-top: var(--space-1); }
.mt-2 { margin-top: var(--space-2); }
.mt-3 { margin-top: var(--space-3); }
.mt-4 { margin-top: var(--space-4); }

.mb-1 { margin-bottom: var(--space-1); }
.mb-2 { margin-bottom: var(--space-2); }
.mb-3 { margin-bottom: var(--space-3); }
.mb-4 { margin-bottom: var(--space-4); }

/* Accessibility */
.sr-only {
    position: absolute;
    width: 1px;
    height: 1px;
    padding: 0;
    margin: -1px;
    overflow: hidden;
    clip: rect(0, 0, 0, 0);
    white-space: nowrap;
    border-width: 0;
}

/* Focus visible for keyboard navigation */
*:focus-visible {
    outline: 2px solid var(--accent-blue);
    outline-offset: 2px;
}

webapp/static/styles_sleek.css.content:
/* ==================== VOUCH BEACON - SLEEK MINIMAL UI ==================== */
/* Premium 5-Star Design - Apple/Linear/Stripe Inspired */

/* Import Clean Typography */
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&display=swap');

:root {
    /* Minimal Color Palette */
    --bg-primary: #0A0A0A;
    --bg-secondary: #111111;
    --bg-tertiary: #1A1A1A;
    --bg-elevated: #222222;

    /* Glass Effect - Subtle */
    --glass: rgba(255, 255, 255, 0.03);
    --glass-hover: rgba(255, 255, 255, 0.06);
    --glass-border: rgba(255, 255, 255, 0.08);

    /* Accent - Single color, used sparingly */
    --accent: #0066FF;
    --accent-hover: #0052CC;
    --accent-soft: rgba(0, 102, 255, 0.1);
    --accent-glow: rgba(0, 102, 255, 0.2);

    /* Text Hierarchy */
    --text-primary: #FFFFFF;
    --text-secondary: rgba(255, 255, 255, 0.7);
    --text-tertiary: rgba(255, 255, 255, 0.5);
    --text-quaternary: rgba(255, 255, 255, 0.3);

    /* Status Colors - Muted */
    --success: #00D66A;
    --warning: #FFA500;
    --error: #FF4444;

    /* Spacing - 4pt grid */
    --space-1: 4px;
    --space-2: 8px;
    --space-3: 12px;
    --space-4: 16px;
    --space-5: 20px;
    --space-6: 24px;
    --space-8: 32px;
    --space-10: 40px;
    --space-12: 48px;
    --space-16: 64px;

    /* Typography */
    --font: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;

    --text-xs: 11px;
    --text-sm: 13px;
    --text-base: 15px;
    --text-lg: 17px;
    --text-xl: 20px;
    --text-2xl: 24px;
    --text-3xl: 32px;
    --text-4xl: 40px;

    /* Shadows - Minimal */
    --shadow-sm: 0 1px 2px rgba(0, 0, 0, 0.3);
    --shadow-md: 0 4px 8px rgba(0, 0, 0, 0.4);
    --shadow-lg: 0 8px 16px rgba(0, 0, 0, 0.5);

    /* Radius */
    --radius-sm: 8px;
    --radius-md: 12px;
    --radius-lg: 16px;
    --radius-xl: 20px;
    --radius-full: 9999px;

    /* Transitions - Fast & Subtle */
    --ease: cubic-bezier(0.4, 0, 0.2, 1);
    --duration: 200ms;

    /* Blur */
    --blur: blur(20px);
}

/* ==================== RESET ==================== */

* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

html {
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
}

body {
    font-family: var(--font);
    font-size: var(--text-base);
    font-weight: 400;
    line-height: 1.5;
    color: var(--text-primary);
    background: var(--bg-primary);
    min-height: 100vh;
}

/* Minimal Selection */
::selection {
    background: var(--accent-soft);
    color: var(--text-primary);
}

/* Clean Scrollbar */
::-webkit-scrollbar {
    width: 6px;
    height: 6px;
}

::-webkit-scrollbar-track {
    background: transparent;
}

::-webkit-scrollbar-thumb {
    background: var(--glass-border);
    border-radius: var(--radius-full);
}

::-webkit-scrollbar-thumb:hover {
    background: var(--accent);
}

/* ==================== LAYOUT ==================== */

.loading-screen {
    position: fixed;
    inset: 0;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    background: var(--bg-primary);
    z-index: 1000;
}

.loading-spinner {
    width: 32px;
    height: 32px;
    border: 2px solid var(--glass-border);
    border-top-color: var(--accent);
    border-radius: var(--radius-full);
    animation: spin 0.8s linear infinite;
}

@keyframes spin {
    to { transform: rotate(360deg); }
}

.loading-text {
    margin-top: var(--space-4);
    font-size: var(--text-sm);
    color: var(--text-tertiary);
}

.app-container {
    min-height: 100vh;
    display: flex;
    flex-direction: column;
}

/* ==================== HEADER ==================== */

.app-header {
    position: sticky;
    top: 0;
    z-index: 100;
    background: var(--glass);
    backdrop-filter: var(--blur);
    -webkit-backdrop-filter: var(--blur);
    border-bottom: 1px solid var(--glass-border);
}

.header-content {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: var(--space-4) var(--space-6);
    max-width: 1000px;
    margin: 0 auto;
}

.app-logo {
    font-size: var(--text-lg);
    font-weight: 600;
    letter-spacing: -0.02em;
    color: var(--text-primary);
}

.header-right {
    display: flex;
    gap: var(--space-2);
}

.icon-btn {
    position: relative;
    display: flex;
    align-items: center;
    justify-content: center;
    width: 36px;
    height: 36px;
    background: transparent;
    border: none;
    border-radius: var(--radius-sm);
    color: var(--text-tertiary);
    cursor: pointer;
    transition: all var(--duration) var(--ease);
}

.icon-btn:hover {
    background: var(--glass-hover);
    color: var(--text-primary);
}

.notification-badge {
    position: absolute;
    top: 4px;
    right: 4px;
    min-width: 16px;
    height: 16px;
    padding: 0 4px;
    background: var(--accent);
    color: white;
    font-size: 10px;
    font-weight: 600;
    border-radius: var(--radius-full);
    display: flex;
    align-items: center;
    justify-content: center;
}

/* Search */
.search-bar {
    padding: 0 var(--space-6) var(--space-4);
    max-width: 1000px;
    margin: 0 auto;
    width: 100%;
}

.search-bar input {
    width: 100%;
    padding: var(--space-3) var(--space-4);
    background: var(--glass);
    border: 1px solid var(--glass-border);
    border-radius: var(--radius-md);
    color: var(--text-primary);
    font-family: var(--font);
    font-size: var(--text-sm);
    outline: none;
    transition: all var(--duration) var(--ease);
}

.search-bar input:focus {
    border-color: var(--accent);
    background: var(--glass-hover);
}

.search-bar input::placeholder {
    color: var(--text-quaternary);
}

/* ==================== NAVIGATION ==================== */

.tab-nav {
    display: flex;
    gap: var(--space-1);
    padding: var(--space-3) var(--space-6);
    background: var(--bg-secondary);
    border-bottom: 1px solid var(--glass-border);
    max-width: 1000px;
    margin: 0 auto;
    width: 100%;
}

.tab-btn {
    display: flex;
    align-items: center;
    gap: var(--space-2);
    padding: var(--space-2) var(--space-4);
    background: transparent;
    border: none;
    border-radius: var(--radius-sm);
    color: var(--text-tertiary);
    font-family: var(--font);
    font-size: var(--text-sm);
    font-weight: 500;
    cursor: pointer;
    transition: all var(--duration) var(--ease);
}

.tab-btn:hover {
    background: var(--glass);
    color: var(--text-secondary);
}

.tab-btn.active {
    background: var(--accent-soft);
    color: var(--accent);
}

/* ==================== CONTENT ==================== */

.main-content {
    flex: 1;
    max-width: 1000px;
    margin: 0 auto;
    padding: var(--space-8) var(--space-6);
    width: 100%;
}

.tab-content {
    display: none;
}

.tab-content.active {
    display: block;
    animation: fadeIn 0.2s var(--ease);
}

@keyframes fadeIn {
    from { opacity: 0; }
    to { opacity: 1; }
}

/* ==================== CARDS ==================== */

.section-card {
    background: var(--glass);
    border: 1px solid var(--glass-border);
    border-radius: var(--radius-lg);
    padding: var(--space-6);
    transition: all var(--duration) var(--ease);
}

.section-card:hover {
    background: var(--glass-hover);
}

/* ==================== PROFILE ==================== */

.profile-hero {
    text-align: center;
    padding: var(--space-12) var(--space-6);
    background: var(--glass);
    border: 1px solid var(--glass-border);
    border-radius: var(--radius-xl);
    margin-bottom: var(--space-8);
}

.profile-avatar-large {
    width: 96px;
    height: 96px;
    margin: 0 auto var(--space-6);
}

.avatar-placeholder {
    width: 100%;
    height: 100%;
    background: linear-gradient(135deg, var(--accent), #00D66A);
    border-radius: var(--radius-full);
    display: flex;
    align-items: center;
    justify-content: center;
}

.avatar-placeholder svg {
    color: white;
    opacity: 0.9;
}

.profile-name {
    font-size: var(--text-2xl);
    font-weight: 600;
    color: var(--text-primary);
    margin-bottom: var(--space-1);
    letter-spacing: -0.03em;
}

.profile-username {
    font-size: var(--text-sm);
    color: var(--text-tertiary);
    margin-bottom: var(--space-8);
}

.profile-stats-row {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(140px, 1fr));
    gap: var(--space-4);
}

.stat-box {
    padding: var(--space-5) var(--space-4);
    background: var(--bg-secondary);
    border: 1px solid var(--glass-border);
    border-radius: var(--radius-md);
    transition: all var(--duration) var(--ease);
}

.stat-box:hover {
    border-color: var(--accent);
    transform: translateY(-2px);
}

.stat-value {
    font-size: var(--text-3xl);
    font-weight: 700;
    color: var(--text-primary);
    margin-bottom: var(--space-1);
    letter-spacing: -0.03em;
}

.stat-label {
    font-size: var(--text-xs);
    color: var(--text-tertiary);
    text-transform: uppercase;
    letter-spacing: 0.05em;
    font-weight: 500;
}

/* ==================== BUTTONS ==================== */

.btn-primary {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: var(--space-2);
    padding: var(--space-3) var(--space-5);
    background: var(--accent);
    border: none;
    border-radius: var(--radius-sm);
    color: white;
    font-family: var(--font);
    font-size: var(--text-sm);
    font-weight: 500;
    cursor: pointer;
    transition: all var(--duration) var(--ease);
}

.btn-primary:hover {
    background: var(--accent-hover);
    transform: translateY(-1px);
}

.btn-primary:active {
    transform: translateY(0);
}

.btn-secondary {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: var(--space-2);
    padding: var(--space-3) var(--space-5);
    background: transparent;
    border: 1px solid var(--glass-border);
    border-radius: var(--radius-sm);
    color: var(--text-primary);
    font-family: var(--font);
    font-size: var(--text-sm);
    font-weight: 500;
    cursor: pointer;
    transition: all var(--duration) var(--ease);
}

.btn-secondary:hover {
    background: var(--glass);
    border-color: var(--accent);
}

/* ==================== VOUCH CARDS ==================== */

.vouch-card {
    padding: var(--space-4);
    background: var(--glass);
    border: 1px solid var(--glass-border);
    border-radius: var(--radius-md);
    margin-bottom: var(--space-3);
    transition: all var(--duration) var(--ease);
}

.vouch-card:hover {
    background: var(--glass-hover);
    border-color: var(--accent);
}

.vouch-card-header {
    display: flex;
    align-items: center;
    gap: var(--space-3);
    margin-bottom: var(--space-3);
}

.vouch-avatar {
    width: 36px;
    height: 36px;
    background: linear-gradient(135deg, var(--accent), #00D66A);
    border-radius: var(--radius-full);
    display: flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
}

.vouch-info {
    flex: 1;
}

.vouch-username {
    font-weight: 500;
    font-size: var(--text-sm);
    color: var(--text-primary);
}

.vouch-timestamp {
    font-size: var(--text-xs);
    color: var(--text-quaternary);
}

.vouch-comment {
    padding: var(--space-3);
    background: var(--bg-secondary);
    border-radius: var(--radius-sm);
    font-size: var(--text-sm);
    color: var(--text-secondary);
}

/* ==================== BADGES ==================== */

.badge-item {
    display: inline-flex;
    align-items: center;
    gap: var(--space-2);
    padding: var(--space-1) var(--space-3);
    background: var(--glass);
    border: 1px solid var(--glass-border);
    border-radius: var(--radius-full);
    font-size: var(--text-xs);
    font-weight: 500;
    color: var(--text-tertiary);
    transition: all var(--duration) var(--ease);
}

.badge-item:hover {
    border-color: var(--accent);
    color: var(--text-primary);
}

/* ==================== LEADERBOARD ==================== */

.leaderboard-item {
    display: flex;
    align-items: center;
    gap: var(--space-4);
    padding: var(--space-4);
    background: var(--glass);
    border: 1px solid var(--glass-border);
    border-radius: var(--radius-md);
    margin-bottom: var(--space-3);
    transition: all var(--duration) var(--ease);
}

.leaderboard-item:hover {
    background: var(--glass-hover);
    border-color: var(--accent);
}

.leaderboard-rank {
    font-size: var(--text-xl);
    font-weight: 700;
    color: var(--text-tertiary);
    min-width: 32px;
}

.leaderboard-rank.top-1 { color: #FFD700; }
.leaderboard-rank.top-2 { color: #C0C0C0; }
.leaderboard-rank.top-3 { color: #CD7F32; }

/* ==================== TOAST ==================== */

.toast {
    position: fixed;
    bottom: var(--space-6);
    right: var(--space-6);
    padding: var(--space-4) var(--space-5);
    background: var(--bg-elevated);
    border: 1px solid var(--glass-border);
    border-radius: var(--radius-md);
    color: var(--text-primary);
    font-size: var(--text-sm);
    font-weight: 500;
    z-index: 1000;
    animation: slideIn 0.2s var(--ease);
}

@keyframes slideIn {
    from {
        transform: translateY(20px);
        opacity: 0;
    }
    to {
        transform: translateY(0);
        opacity: 1;
    }
}

.toast.success { border-color: var(--success); }
.toast.error { border-color: var(--error); }

/* ==================== EMPTY STATE ==================== */

.empty-state {
    text-align: center;
    padding: var(--space-16);
    color: var(--text-tertiary);
}

.empty-state-title {
    font-size: var(--text-lg);
    font-weight: 600;
    color: var(--text-secondary);
    margin-bottom: var(--space-2);
}

.empty-state-description {
    font-size: var(--text-sm);
    color: var(--text-tertiary);
}

/* ==================== SECTIONS ==================== */

.section-container {
    margin-bottom: var(--space-8);
}

.section-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    margin-bottom: var(--space-4);
}

.section-title {
    font-size: var(--text-lg);
    font-weight: 600;
    color: var(--text-primary);
    letter-spacing: -0.02em;
}

.section-count {
    font-size: var(--text-sm);
    color: var(--text-tertiary);
    font-weight: 500;
}

.profile-actions {
    margin-top: var(--space-8);
    display: flex;
    gap: var(--space-3);
    justify-content: center;
}

/* ==================== LISTS ==================== */

.vouches-list {
    display: flex;
    flex-direction: column;
    gap: var(--space-3);
}

.leaderboard-list {
    display: flex;
    flex-direction: column;
}

/* ==================== LEADERBOARD TABS ==================== */

.leaderboard-tabs {
    display: flex;
    gap: var(--space-2);
    margin-bottom: var(--space-6);
    padding: var(--space-1);
    background: var(--glass);
    border: 1px solid var(--glass-border);
    border-radius: var(--radius-md);
}

.lb-tab-btn {
    flex: 1;
    padding: var(--space-2) var(--space-4);
    background: transparent;
    border: none;
    border-radius: var(--radius-sm);
    color: var(--text-tertiary);
    font-family: var(--font);
    font-size: var(--text-sm);
    font-weight: 500;
    cursor: pointer;
    transition: all var(--duration) var(--ease);
}

.lb-tab-btn:hover {
    color: var(--text-secondary);
}

.lb-tab-btn.active {
    background: var(--accent);
    color: white;
}

/* ==================== NETWORK VIZ ==================== */

.network-info {
    padding: var(--space-4);
    background: var(--accent-soft);
    border: 1px solid var(--accent);
    border-radius: var(--radius-md);
    margin-bottom: var(--space-6);
}

.network-info p {
    font-size: var(--text-sm);
    color: var(--text-secondary);
    text-align: center;
}

.network-visualization {
    width: 100%;
    height: 500px;
    background: var(--glass);
    border: 1px solid var(--glass-border);
    border-radius: var(--radius-lg);
    margin-bottom: var(--space-4);
}

.network-legend {
    display: flex;
    justify-content: center;
    gap: var(--space-6);
}

.legend-item {
    display: flex;
    align-items: center;
    gap: var(--space-2);
    font-size: var(--text-xs);
    color: var(--text-tertiary);
}

.legend-dot {
    width: 10px;
    height: 10px;
    border-radius: var(--radius-full);
}

.legend-you { background: var(--accent); }
.legend-voucher { background: #00D66A; }
.legend-vouched { background: #FFA500; }

/* ==================== SKELETON LOADING ==================== */

.skeleton-card {
    padding: var(--space-4);
    background: var(--glass);
    border: 1px solid var(--glass-border);
    border-radius: var(--radius-md);
    margin-bottom: var(--space-3);
    position: relative;
    overflow: hidden;
}

.skeleton-card::before {
    content: '';
    position: absolute;
    top: 0;
    left: -100%;
    width: 100%;
    height: 100%;
    background: linear-gradient(90deg,
        transparent,
        rgba(255, 255, 255, 0.03),
        transparent
    );
    animation: shimmer 1.5s infinite;
}

@keyframes shimmer {
    to { left: 100%; }
}

.skeleton-line {
    height: 14px;
    background: var(--glass-hover);
    border-radius: var(--radius-sm);
    margin-bottom: var(--space-2);
}

.skeleton-line.short {
    width: 60%;
}

.skeleton-circle {
    width: 40px;
    height: 40px;
    background: var(--glass-hover);
    border-radius: var(--radius-full);
}

/* ==================== SUGGESTIONS ==================== */

.suggestions-container {
    margin-bottom: var(--space-8);
}

.suggestions-container h3 {
    font-size: var(--text-lg);
    font-weight: 600;
    color: var(--text-primary);
    margin-bottom: var(--space-3);
}

.suggestions-container p {
    font-size: var(--text-sm);
    color: var(--text-tertiary);
    margin-bottom: var(--space-4);
}

.suggestion-item {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: var(--space-4);
    background: var(--glass);
    border: 1px solid var(--glass-border);
    border-radius: var(--radius-md);
    margin-bottom: var(--space-3);
    transition: all var(--duration) var(--ease);
}

.suggestion-item:hover {
    background: var(--glass-hover);
    border-color: var(--accent);
}

.suggestion-info {
    flex: 1;
}

.suggestion-username {
    font-weight: 500;
    color: var(--text-primary);
    margin-bottom: var(--space-1);
}

.suggestion-meta {
    font-size: var(--text-xs);
    color: var(--text-quaternary);
}

/* ==================== RANK DISPLAY ==================== */

.rank-display {
    display: inline-flex;
    align-items: center;
    gap: var(--space-2);
    padding: var(--space-2) var(--space-4);
    background: var(--accent-soft);
    border: 1px solid var(--accent);
    border-radius: var(--radius-full);
    margin-top: var(--space-4);
}

.rank-display span {
    font-size: var(--text-sm);
    font-weight: 600;
}

.rank-progress {
    width: 100%;
    max-width: 300px;
    margin: var(--space-6) auto 0;
}

.rank-progress-header {
    display: flex;
    justify-content: space-between;
    margin-bottom: var(--space-2);
    font-size: var(--text-xs);
    color: var(--text-tertiary);
}

.rank-progress-bar {
    height: 6px;
    background: var(--glass);
    border-radius: var(--radius-full);
    overflow: hidden;
}

.rank-progress-fill {
    height: 100%;
    background: var(--accent);
    border-radius: var(--radius-full);
    transition: width 0.5s var(--ease);
}

/* ==================== BADGES CONTAINER ==================== */

.badges-container {
    display: flex;
    flex-wrap: wrap;
    justify-content: center;
    gap: var(--space-2);
    margin-top: var(--space-6);
}

/* ==================== RESPONSIVE ==================== */

@media (max-width: 768px) {
    .main-content {
        padding: var(--space-6) var(--space-4);
    }

    .profile-hero {
        padding: var(--space-8) var(--space-4);
    }

    .profile-stats-row {
        grid-template-columns: 1fr 1fr;
    }

    .tab-btn span {
        display: none;
    }

    .network-visualization {
        height: 400px;
    }

    .network-legend {
        flex-wrap: wrap;
        gap: var(--space-3);
    }
}

@media (max-width: 480px) {
    .profile-stats-row {
        grid-template-columns: 1fr;
    }

    .profile-actions {
        flex-direction: column;
    }

    .profile-actions .btn-primary {
        width: 100%;
    }
}

/* ==================== ACCESSIBILITY ==================== */

.sr-only {
    position: absolute;
    width: 1px;
    height: 1px;
    padding: 0;
    margin: -1px;
    overflow: hidden;
    clip: rect(0, 0, 0, 0);
    white-space: nowrap;
    border-width: 0;
}

*:focus-visible {
    outline: 2px solid var(--accent);
    outline-offset: 2px;
}

button:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

@media (prefers-reduced-motion: reduce) {
    *,
    *::before,
    *::after {
        animation-duration: 0.01ms !important;
        transition-duration: 0.01ms !important;
    }
}

/* ==================== UTILITIES ==================== */

.text-center { text-align: center; }
.text-left { text-align: left; }
.text-right { text-align: right; }

.mb-2 { margin-bottom: var(--space-2); }
.mb-4 { margin-bottom: var(--space-4); }
.mb-6 { margin-bottom: var(--space-6); }
.mb-8 { margin-bottom: var(--space-8); }

.mt-2 { margin-top: var(--space-2); }
.mt-4 { margin-top: var(--space-4); }
.mt-6 { margin-top: var(--space-6); }
.mt-8 { margin-top: var(--space-8); }

.flex { display: flex; }
.flex-col { flex-direction: column; }
.items-center { align-items: center; }
.justify-center { justify-content: center; }
.gap-2 { gap: var(--space-2); }
.gap-4 { gap: var(--space-4); }

api_beacon.py.content:
"""
Vouch Beacon REST API
FastAPI endpoints for the Vouch Beacon ecosystem
"""
import os
import logging
from contextlib import asynccontextmanager
from typing import Optional
from fastapi import FastAPI, Request, HTTPException
from fastapi.responses import HTMLResponse, JSONResponse, RedirectResponse
from fastapi.staticfiles import StaticFiles
from fastapi.middleware.cors import CORSMiddleware
from pydantic import BaseModel
from telegram import Update
from database_beacon import db

logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

# Configuration
BOT_TOKEN = os.getenv("BOT_TOKEN")
WEBHOOK_URL = os.getenv("WEBHOOK_URL")
ADMIN_ID = int(os.getenv("ADMIN_ID", "0"))

# Global bot application
bot_app = None


@asynccontextmanager
async def lifespan(app: FastAPI):
    """Lifecycle manager for FastAPI app"""
    global bot_app

    # Startup
    logger.info("Starting Vouch Beacon application...")

    # Connect to database
    await db.connect()

    # Initialize bot
    try:
        from bot_beacon import create_bot_application
        bot_app = create_bot_application()
        await bot_app.initialize()
        await bot_app.start()
        logger.info("Telegram bot initialized successfully")
    except Exception as e:
        logger.error(f"Failed to initialize Telegram bot: {e}")
        logger.warning("Application will continue without bot functionality")
        bot_app = None

    logger.info("Vouch Beacon application started successfully")

    yield

    # Shutdown
    logger.info("Shutting down application...")

    if bot_app:
        try:
            await bot_app.stop()
            await bot_app.shutdown()
        except Exception as e:
            logger.error(f"Error shutting down bot: {e}")

    await db.disconnect()

    logger.info("Application shutdown complete")


# Create FastAPI app
app = FastAPI(
    title="Vouch Beacon",
    description="Hybrid group-based vouch system with private actions, public recognition",
    version="2.0.0",
    lifespan=lifespan
)

# CORS middleware
app.add_middleware(
    CORSMiddleware,
    allow_origins=["*"],
    allow_credentials=True,
    allow_methods=["*"],
    allow_headers=["*"],
)


# Mount static files
try:
    app.mount("/static", StaticFiles(directory="webapp/static"), name="static")
except Exception as e:
    logger.warning(f"Could not mount static files: {e}")


# Pydantic models
class VouchCreate(BaseModel):
    from_telegram_id: int
    to_username: str
    group_chat_id: Optional[int] = None
    comment: Optional[str] = None


class VouchUpdate(BaseModel):
    from_telegram_id: int
    comment: str


class VouchUndo(BaseModel):
    from_telegram_id: int


class MagicLinkRequest(BaseModel):
    telegram_user_id: int


# Middleware to add no-cache headers
@app.middleware("http")
async def add_no_cache_headers(request: Request, call_next):
    """Add no-cache headers to prevent stale cached files"""
    response = await call_next(request)

    if (request.url.path == "/" or
        request.url.path.endswith('.html') or
        request.url.path.endswith('.js') or
        request.url.path.endswith('.css')):
        response.headers["Cache-Control"] = "no-cache, no-store, must-revalidate"
        response.headers["Pragma"] = "no-cache"
        response.headers["Expires"] = "0"

    return response


# ==================== WEB APP ROUTES ====================

@app.get("/", response_class=HTMLResponse)
async def serve_webapp():
    """Serve the main WebApp"""
    try:
        with open("webapp/index.html", "r", encoding="utf-8") as f:
            html_content = f.read()
        return HTMLResponse(content=html_content)
    except FileNotFoundError:
        return HTMLResponse(
            content="<h1>Vouch Beacon</h1><p>WebApp frontend not found. Please ensure webapp/index.html exists.</p>",
            status_code=200
        )


@app.get("/auth")
async def magic_link_auth(token: str):
    """
    Magic Link authentication endpoint
    Verifies JWT token and sets session cookie
    """
    try:
        telegram_user_id = db.verify_magic_link(token)

        if not telegram_user_id:
            return HTMLResponse(
                content="<h1>Invalid or Expired Link</h1><p>This magic link has expired or is invalid. Please request a new one from the bot.</p>",
                status_code=400
            )

        # Get user data
        user = await db.get_user_by_telegram_id(telegram_user_id)
        if not user:
            return HTMLResponse(
                content="<h1>User Not Found</h1><p>Please connect with the bot first.</p>",
                status_code=404
            )

        # Redirect to profile with auth cookie
        response = RedirectResponse(url=f"/?user_id={telegram_user_id}")
        response.set_cookie(
            key="vouch_beacon_auth",
            value=token,
            httponly=True,
            max_age=900,  # 15 minutes
            samesite="lax"
        )

        return response

    except Exception as e:
        logger.error(f"Magic link auth error: {e}")
        return HTMLResponse(
            content=f"<h1>Error</h1><p>An error occurred: {str(e)}</p>",
            status_code=500
        )


# ==================== API ENDPOINTS ====================

@app.get("/health")
async def health_check():
    """Health check endpoint"""
    return {
        "status": "healthy",
        "service": "vouch-beacon",
        "database": "connected" if db.pool else "disconnected"
    }


@app.get("/api/bot-info")
async def get_bot_info():
    """Get bot configuration info"""
    return {
        "bot_username": os.getenv("BOT_USERNAME", "VouchBeaconBot")
    }


@app.post("/webhook")
async def webhook(request: Request):
    """Handle Telegram webhook updates"""
    if not bot_app:
        return {"status": "error", "message": "Bot not initialized"}

    try:
        data = await request.json()
        update = Update.de_json(data, bot_app.bot)

        # Process update
        await bot_app.process_update(update)

        return {"status": "ok"}
    except Exception as e:
        logger.error(f"Webhook error: {e}")
        return {"status": "error", "message": str(e)}


# ==================== VOUCH ENDPOINTS ====================

@app.post("/api/vouches")
async def create_vouch(vouch: VouchCreate):
    """
    Create a new vouch
    POST /api/vouches
    Body: {from_telegram_id, to_username, group_chat_id?, comment?}
    Returns: {vouch_id, to_user_telegram_id, created_at}
    """
    try:
        result = await db.create_vouch(
            from_telegram_id=vouch.from_telegram_id,
            to_username=vouch.to_username,
            group_chat_id=vouch.group_chat_id,
            comment=vouch.comment
        )

        if "error" in result:
            raise HTTPException(status_code=400, detail=result["error"])

        return result
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"Error creating vouch: {e}")
        raise HTTPException(status_code=500, detail=str(e))


@app.put("/api/vouches/{vouch_id}")
async def update_vouch(vouch_id: int, vouch_update: VouchUpdate):
    """
    Update vouch comment
    PUT /vouches/{vouch_id}
    Body: {from_telegram_id, comment}
    """
    try:
        result = await db.update_vouch_comment(
            vouch_id=vouch_id,
            from_telegram_id=vouch_update.from_telegram_id,
            comment=vouch_update.comment
        )

        if "error" in result:
            if result["error"] == "Vouch not found":
                raise HTTPException(status_code=404, detail=result["error"])
            else:
                raise HTTPException(status_code=403, detail=result["error"])

        return result
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"Error updating vouch: {e}")
        raise HTTPException(status_code=500, detail=str(e))


@app.delete("/api/vouches/{vouch_id}")
async def undo_vouch(vouch_id: int, vouch_undo: VouchUndo):
    """
    Undo/soft delete a vouch
    DELETE /vouches/{vouch_id}
    Body: {from_telegram_id}
    """
    try:
        result = await db.undo_vouch(
            vouch_id=vouch_id,
            from_telegram_id=vouch_undo.from_telegram_id
        )

        if "error" in result:
            if result["error"] == "Vouch not found":
                raise HTTPException(status_code=404, detail=result["error"])
            else:
                raise HTTPException(status_code=403, detail=result["error"])

        return result
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"Error undoing vouch: {e}")
        raise HTTPException(status_code=500, detail=str(e))


# ==================== USER ENDPOINTS ====================

@app.get("/api/users/{telegram_user_id}")
async def get_user_profile(telegram_user_id: int):
    """
    Get user profile with stats
    GET /users/{telegram_user_id}
    Returns: {user, vouches_received, vouches_given, vouches_received_list, vouches_given_list}
    """
    try:
        # Get user stats
        stats = await db.get_user_stats(telegram_user_id)

        if "error" in stats:
            raise HTTPException(status_code=404, detail=stats["error"])

        # Get recent vouches
        vouches_received_list = await db.get_vouches_for_user(telegram_user_id, limit=20)
        vouches_given_list = await db.get_vouches_by_user(telegram_user_id, limit=20)

        return {
            **stats,
            "vouches_received_list": vouches_received_list,
            "vouches_given_list": vouches_given_list
        }
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"Error getting user profile: {e}")
        raise HTTPException(status_code=500, detail=str(e))


# ==================== LEADERBOARD ENDPOINTS ====================

@app.get("/api/leaderboards")
async def get_leaderboards(type: str = "most_vouched", limit: int = 25):
    """
    Get leaderboard data
    GET /leaderboards?type=most_vouched&limit=25
    Types: most_vouched, top_givers
    """
    try:
        leaderboard = await db.get_leaderboard(board_type=type, limit=limit)
        return {
            "leaderboard": leaderboard,
            "type": type
        }
    except Exception as e:
        logger.error(f"Error getting leaderboard: {e}")
        raise HTTPException(status_code=500, detail=str(e))


# ==================== MAGIC LINK AUTHENTICATION ====================

@app.post("/api/auth/magic-link")
async def create_magic_link(request: MagicLinkRequest):
    """
    Generate magic link for user authentication
    POST /auth/magic-link
    Body: {telegram_user_id}
    Returns: {magic_link}
    """
    try:
        magic_link = db.generate_magic_link(request.telegram_user_id)
        return {"magic_link": magic_link}
    except Exception as e:
        logger.error(f"Error generating magic link: {e}")
        raise HTTPException(status_code=500, detail=str(e))


# ==================== ANALYTICS ENDPOINTS ====================

@app.get("/api/analytics")
async def get_analytics():
    """Get analytics summary"""
    try:
        analytics = await db.get_analytics_summary()
        return analytics
    except Exception as e:
        logger.error(f"Error getting analytics: {e}")
        raise HTTPException(status_code=500, detail=str(e))


# ==================== IMPROVEMENT ENDPOINTS ====================

@app.get("/api/users/{telegram_user_id}/suggestions")
async def get_connection_suggestions(telegram_user_id: int, limit: int = 5):
    """
    Get connection suggestions for a user
    GET /api/users/{telegram_user_id}/suggestions?limit=5
    Returns: List of suggested users to vouch for
    """
    try:
        from improvements_beacon import ConnectionSuggester
        suggester = ConnectionSuggester(db)
        suggestions = await suggester.get_suggested_connections(telegram_user_id, limit)
        return {"suggestions": suggestions}
    except Exception as e:
        logger.error(f"Error getting suggestions: {e}")
        raise HTTPException(status_code=500, detail=str(e))


@app.get("/api/users/{telegram_user_id}/streak")
async def get_user_streak(telegram_user_id: int):
    """
    Get user's current daily streak
    GET /api/users/{telegram_user_id}/streak
    Returns: {streak: int, last_active: datetime}
    """
    try:
        from improvements_beacon import StreakSystem
        streak_sys = StreakSystem(db)
        streak = await streak_sys.get_user_streak(telegram_user_id)
        user = await db.get_user_by_telegram_id(telegram_user_id)

        return {
            "streak": streak,
            "last_active": user['last_seen_at'].isoformat() if user else None
        }
    except Exception as e:
        logger.error(f"Error getting streak: {e}")
        raise HTTPException(status_code=500, detail=str(e))


@app.get("/api/moderation/violations/{telegram_user_id}")
async def get_user_violations(telegram_user_id: int):
    """
    Get violation count for a user (admin only)
    GET /api/moderation/violations/{telegram_user_id}
    Returns: {count: int, action: str}
    """
    try:
        from improvements_beacon import ProgressiveModerator
        moderator = ProgressiveModerator(db)
        count, action = await moderator.check_user_violations(telegram_user_id)

        return {
            "user_id": telegram_user_id,
            "violation_count": count,
            "next_action": action,
            "is_muted": moderator.is_muted(telegram_user_id)
        }
    except Exception as e:
        logger.error(f"Error getting violations: {e}")
        raise HTTPException(status_code=500, detail=str(e))


if __name__ == "__main__":
    import uvicorn
    port = int(os.getenv("PORT", "5000"))

    is_production = os.getenv("REPLIT_ENVIRONMENT", "development") == "production"

    uvicorn.run(
        "api_beacon:app",
        host="0.0.0.0",
        port=port,
        reload=not is_production
    )

