// ==================== UTILITY FUNCTIONS ====================

function getInitials(name) {
    if (!name) return '?';
    const parts = name.trim().split(' ');
    if (parts.length === 1) return parts[0].substring(0, 2).toUpperCase();
    return (parts[0][0] + parts[1][0]).toUpperCase();
}

function getTimeAgo(timestamp) {
    const now = Date.now();
    const then = new Date(timestamp).getTime();
    const diff = now - then;

    const seconds = Math.floor(diff / 1000);
    const minutes = Math.floor(seconds / 60);
    const hours = Math.floor(minutes / 60);
    const days = Math.floor(hours / 24);

    if (days > 7) return new Date(timestamp).toLocaleDateString();
    if (days > 0) return `${days}d ago`;
    if (hours > 0) return `${hours}h ago`;
    if (minutes > 0) return `${minutes}m ago`;
    return 'just now';
}

function escapeHtml(text) {
    const div = document.createElement('div');
    div.textContent = text;
    return div.innerHTML;
}

function showToast(message, type = 'info') {
    const container = document.getElementById('toastContainer');

    const toast = document.createElement('div');
    toast.className = `toast ${type}`;
    toast.textContent = message;

    container.appendChild(toast);

    setTimeout(() => {
        toast.style.opacity = '0';
        setTimeout(() => toast.remove(), 300);
    }, 3000);
}

function showError(message) {
    document.getElementById('loadingScreen').innerHTML = `
        <div style="text-align: center; padding: 32px;">
            <svg width="64" height="64" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" style="color: var(--color-error); margin-bottom: 16px;">
                <circle cx="12" cy="12" r="10"></circle>
                <line x1="15" y1="9" x2="9" y2="15"></line>
                <line x1="9" y1="9" x2="15" y2="15"></line>
            </svg>
            <h2 style="font-size: 20px; margin-bottom: 8px;">Error</h2>
            <p style="color: var(--color-text-tertiary);">${message}</p>
        </div>
    `;
}

// ==================== START APP ====================

document.addEventListener('DOMContentLoaded', init);

webapp/static/app.css.content:
/* LocalVouch - Professional, Clean Design */
/* Reset & Base */
* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

:root {
    --bg-primary: #ffffff;
    --bg-secondary: #f7f9fa;
    --bg-tertiary: #e1e8ed;
    --text-primary: #14171a;
    --text-secondary: #657786;
    --text-tertiary: #aab8c2;
    --border: #e1e8ed;
    --blue: #1da1f2;
    --green: #17bf63;
    --red: #e0245e;
    --orange: #ff9500;
    --yellow: #ffad1f;
    --shadow: rgba(0, 0, 0, 0.08);
}

body {
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
    background: var(--bg-secondary);
    color: var(--text-primary);
    line-height: 1.5;
    -webkit-font-smoothing: antialiased;
    padding-bottom: 70px; /* Space for nav */
}

#app {
    max-width: 600px;
    margin: 0 auto;
    min-height: 100vh;
}

/* Navigation */
.nav {
    position: fixed;
    bottom: 0;
    left: 0;
    right: 0;
    background: var(--bg-primary);
    border-top: 1px solid var(--border);
    display: flex;
    justify-content: space-around;
    padding: 8px 0;
    z-index: 100;
    max-width: 600px;
    margin: 0 auto;
}

.nav-btn {
    flex: 1;
    border: none;
    background: none;
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 4px;
    padding: 8px;
    cursor: pointer;
    transition: all 0.2s;
    color: var(--text-secondary);
    font-size: 11px;
    font-weight: 500;
}

.nav-btn.active {
    color: var(--blue);
}

.nav-icon {
    font-size: 20px;
}

/* Tabs */
.tab-content {
    display: none;
    padding: 16px;
}

.tab-content.active {
    display: block;
}

/* Container */
.container {
    max-width: 100%;
}

/* Search Box */
.search-box {
    background: var(--bg-primary);
    border-radius: 12px;
    padding: 12px;
    margin-bottom: 16px;
    box-shadow: 0 1px 3px var(--shadow);
}

.search-input {
    width: 100%;
    border: 1px solid var(--border);
    border-radius: 20px;
    padding: 10px 16px;
    font-size: 15px;
    outline: none;
    transition: border-color 0.2s;
}

.search-input:focus {
    border-color: var(--blue);
}

/* Search Results */
.search-results {
    background: var(--bg-primary);
    border-radius: 12px;
    overflow: hidden;
    margin-bottom: 16px;
    box-shadow: 0 1px 3px var(--shadow);
}

.search-results:empty {
    display: none;
}

/* Section */
.section {
    background: var(--bg-primary);
    border-radius: 12px;
    padding: 16px;
    margin-bottom: 16px;
    box-shadow: 0 1px 3px var(--shadow);
}

.section-title {
    font-size: 18px;
    font-weight: 700;
    margin-bottom: 12px;
    color: var(--text-primary);
}

.section-subtitle {
    font-size: 14px;
    color: var(--text-secondary);
    margin-bottom: 16px;
}

/* Profile Card */
.profile-card {
    background: var(--bg-primary);
    border-radius: 12px;
    padding: 20px;
    margin-bottom: 16px;
    box-shadow: 0 1px 3px var(--shadow);
    text-align: center;
}

.profile-header {
    margin-bottom: 16px;
}

.profile-name {
    font-size: 20px;
    font-weight: 700;
    color: var(--text-primary);
    margin-bottom: 4px;
}

.profile-username {
    font-size: 14px;
    color: var(--text-secondary);
}

/* Rank Badge */
.rank-badge {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    padding: 8px 16px;
    border-radius: 20px;
    font-size: 13px;
    font-weight: 700;
    margin: 12px 0;
    letter-spacing: 0.5px;
}

.rank-badge.new {
    background: var(--bg-tertiary);
    color: var(--text-secondary);
}

.rank-badge.building {
    background: #fff3e0;
    color: var(--orange);
}

.rank-badge.trusted {
    background: #e8f5e9;
    color: var(--green);
}

.rank-badge.top_rated {
    background: #fff9c4;
    color: #f57f17;
}

.rank-badge.mixed {
    background: #fff3e0;
    color: var(--orange);
}

.rank-badge.caution {
    background: #ffebee;
    color: var(--red);
}

.rank-emoji {
    font-size: 16px;
}

.rank-text {
    font-size: 12px;
}

/* Vouch Counts */
.vouch-counts {
    display: flex;
    justify-content: center;
    gap: 32px;
    margin: 20px 0;
}

.count-item {
    display: flex;
    align-items: center;
    gap: 8px;
}

.count-icon {
    font-size: 24px;
}

.count-number {
    font-size: 24px;
    font-weight: 700;
    color: var(--text-primary);
}

.count-item.thumbs-up .count-number {
    color: var(--green);
}

.count-item.thumbs-down .count-number {
    color: var(--red);
}

/* Progress */
.progress-container {
    margin: 20px 0;
}

.progress-label {
    font-size: 13px;
    color: var(--text-secondary);
    margin-bottom: 8px;
    text-align: center;
}

.progress-bar {
    height: 6px;
    background: var(--bg-tertiary);
    border-radius: 3px;
    overflow: hidden;
}

.progress-fill {
    height: 100%;
    background: linear-gradient(90deg, var(--blue), var(--green));
    transition: width 0.3s ease;
}

/* Buttons */
.btn {
    border: none;
    border-radius: 24px;
    padding: 12px 24px;
    font-size: 15px;
    font-weight: 700;
    cursor: pointer;
    transition: all 0.2s;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 8px;
}

.btn-primary {
    background: var(--blue);
    color: white;
}

.btn-primary:hover {
    background: #1a91da;
}

.btn-primary:active {
    transform: scale(0.98);
}

.btn-block {
    width: 100%;
}

/* Thumbs Buttons */
.thumbs-buttons {
    display: flex;
    gap: 12px;
    margin: 20px 0;
}

.thumb-btn {
    flex: 1;
    border: 2px solid var(--border);
    border-radius: 12px;
    padding: 16px;
    background: white;
    cursor: pointer;
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 8px;
    transition: all 0.2s;
    font-size: 14px;
    font-weight: 600;
}

.thumb-btn .thumb-icon {
    font-size: 32px;
}

.thumb-btn.thumb-up:hover {
    border-color: var(--green);
    background: #f1f8f4;
}

.thumb-btn.thumb-up.selected {
    border-color: var(--green);
    background: var(--green);
    color: white;
}

.thumb-btn.thumb-down:hover {
    border-color: var(--red);
    background: #fff5f7;
}

.thumb-btn.thumb-down.selected {
    border-color: var(--red);
    background: var(--red);
    color: white;
}

/* Message Box */
.message-box {
    margin: 16px 0;
}

.message-box textarea {
    width: 100%;
    border: 1px solid var(--border);
    border-radius: 12px;
    padding: 12px;
    font-size: 15px;
    font-family: inherit;
    resize: none;
    outline: none;
}

.message-box textarea:focus {
    border-color: var(--blue);
}

.char-counter {
    text-align: right;
    font-size: 12px;
    color: var(--text-tertiary);
    margin-top: 4px;
    margin-bottom: 12px;
}

/* User Grid */
.user-grid {
    display: grid;
    grid-template-columns: 1fr;
    gap: 12px;
}

.user-card {
    border: 1px solid var(--border);
    border-radius: 12px;
    padding: 16px;
    cursor: pointer;
    transition: all 0.2s;
    background: white;
}

.user-card:hover {
    border-color: var(--blue);
    box-shadow: 0 2px 8px var(--shadow);
}

.user-card-header {
    display: flex;
    justify-content: space-between;
    align-items: flex-start;
    margin-bottom: 8px;
}

.user-card-info {
    flex: 1;
}

.user-card-name {
    font-size: 16px;
    font-weight: 700;
    color: var(--text-primary);
}

.user-card-username {
    font-size: 14px;
    color: var(--text-secondary);
}

.user-card-counts {
    display: flex;
    gap: 12px;
    font-size: 14px;
}

.user-card-counts span {
    display: flex;
    align-items: center;
    gap: 4px;
}

/* Vouch List */
.vouch-list {
    display: flex;
    flex-direction: column;
    gap: 12px;
}

.vouch-item {
    border: 1px solid var(--border);
    border-radius: 12px;
    padding: 12px;
    background: white;
}

.vouch-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 8px;
}

.vouch-user {
    display: flex;
    align-items: center;
    gap: 8px;
    cursor: pointer;
}

.vouch-user:hover {
    text-decoration: underline;
}

.vouch-name {
    font-weight: 600;
    font-size: 14px;
}

.vouch-username {
    font-size: 13px;
    color: var(--text-secondary);
}

.vouch-type {
    font-size: 18px;
}

.vouch-message {
    font-size: 14px;
    color: var(--text-primary);
    margin-bottom: 8px;
}

.vouch-time {
    font-size: 12px;
    color: var(--text-tertiary);
}

.vouch-back-btn {
    background: var(--bg-secondary);
    border: none;
    border-radius: 16px;
    padding: 6px 12px;
    font-size: 12px;
    font-weight: 600;
    color: var(--blue);
    cursor: pointer;
    margin-top: 8px;
}

.vouch-back-btn:hover {
    background: var(--bg-tertiary);
}

/* Activity Feed */
.activity-feed {
    display: flex;
    flex-direction: column;
    gap: 12px;
}

.activity-item {
    padding: 12px;
    border-left: 3px solid var(--blue);
    background: var(--bg-secondary);
    border-radius: 8px;
}

.activity-text {
    font-size: 14px;
    margin-bottom: 4px;
}

.activity-time {
    font-size: 12px;
    color: var(--text-tertiary);
}

/* Groups List */
.groups-list {
    display: flex;
    flex-direction: column;
    gap: 12px;
}

.group-card {
    border: 1px solid var(--border);
    border-radius: 12px;
    padding: 16px;
    background: white;
}

.group-header {
    display: flex;
    align-items: center;
    gap: 12px;
    margin-bottom: 12px;
}

.group-icon {
    font-size: 28px;
}

.group-info {
    flex: 1;
}

.group-name {
    font-size: 16px;
    font-weight: 700;
    color: var(--text-primary);
}

.group-members {
    font-size: 13px;
    color: var(--text-secondary);
}

.group-description {
    font-size: 14px;
    color: var(--text-primary);
    margin-bottom: 12px;
}

.group-join-btn {
    background: var(--blue);
    color: white;
    border: none;
    border-radius: 20px;
    padding: 10px 20px;
    font-size: 14px;
    font-weight: 600;
    cursor: pointer;
    width: 100%;
}

.group-join-btn:hover {
    background: #1a91da;
}

/* Modal */
.modal {
    display: none;
    position: fixed;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background: rgba(0, 0, 0, 0.5);
    z-index: 1000;
    justify-content: center;
    align-items: flex-start;
    overflow-y: auto;
    padding: 20px;
}

.modal.active {
    display: flex;
}

.modal-content {
    background: white;
    border-radius: 16px;
    max-width: 500px;
    width: 100%;
    max-height: 90vh;
    overflow-y: auto;
    position: relative;
    margin: 20px auto;
}

.modal-close {
    position: sticky;
    top: 0;
    right: 0;
    float: right;
    background: var(--bg-secondary);
    border: none;
    width: 32px;
    height: 32px;
    border-radius: 50%;
    font-size: 18px;
    cursor: pointer;
    margin: 12px;
    z-index: 10;
}

.modal-profile {
    padding: 20px;
    text-align: center;
}

.modal-vouches-list {
    display: flex;
    flex-direction: column;
    gap: 12px;
    max-height: 300px;
    overflow-y: auto;
}

.vouches-title {
    font-size: 16px;
    font-weight: 700;
    margin-bottom: 12px;
    text-align: left;
}

/* Toast */
.toast {
    position: fixed;
    top: 20px;
    left: 50%;
    transform: translateX(-50%) translateY(-100px);
    background: var(--text-primary);
    color: white;
    padding: 12px 20px;
    border-radius: 24px;
    font-size: 14px;
    font-weight: 500;
    box-shadow: 0 4px 12px var(--shadow);
    z-index: 2000;
    opacity: 0;
    transition: all 0.3s;
    max-width: 90%;
}

.toast.show {
    opacity: 1;
    transform: translateX(-50%) translateY(0);
}

.toast.success {
    background: var(--green);
}

.toast.error {
    background: var(--red);
}

/* Loading */
.loading-overlay {
    display: none;
    position: fixed;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background: rgba(255, 255, 255, 0.9);
    z-index: 3000;
    justify-content: center;
    align-items: center;
}

.loading-overlay.active {
    display: flex;
}

.spinner {
    width: 40px;
    height: 40px;
    border: 3px solid var(--border);
    border-top-color: var(--blue);
    border-radius: 50%;
    animation: spin 0.8s linear infinite;
}

@keyframes spin {
    to {
        transform: rotate(360deg);
    }
}

/* Empty States */
.empty-state {
    text-align: center;
    padding: 40px 20px;
    color: var(--text-secondary);
}

.empty-state-icon {
    font-size: 48px;
    margin-bottom: 12px;
}

.empty-state-text {
    font-size: 15px;
}

/* Utilities */
.hide {
    display: none !important;
}

.text-center {
    text-align: center;
}

.text-muted {
    color: var(--text-secondary);
}

/* Responsive */
@media (max-width: 480px) {
    .profile-name {
        font-size: 18px;
    }

    .section-title {
        font-size: 16px;
    }

    .thumbs-buttons {
        flex-direction: row;
    }

    .thumb-btn .thumb-icon {
        font-size: 28px;
    }
}

webapp/static/styles_premium.css.content:
/* ==================== VOUCH BEACON PREMIUM UI ==================== */
/* 5-Star Professional Design System */

/* Import Premium Fonts */
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800&family=Space+Grotesk:wght@500;600;700&display=swap');

/* CSS Variables - Premium Design Tokens */
:root {
    /* Premium Color Palette - Sophisticated Gradients */
    --color-bg-primary: #0B0D17;
    --color-bg-secondary: #111827;
    --color-bg-tertiary: #1F2937;
    --color-bg-elevated: #374151;

    /* Glassmorphism Backgrounds */
    --glass-bg: rgba(255, 255, 255, 0.05);
    --glass-bg-strong: rgba(255, 255, 255, 0.08);
    --glass-border: rgba(255, 255, 255, 0.1);
    --glass-shadow: 0 8px 32px 0 rgba(0, 0, 0, 0.37);

    /* Premium Gradients */
    --gradient-primary: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
    --gradient-secondary: linear-gradient(135deg, #f093fb 0%, #f5576c 100%);
    --gradient-success: linear-gradient(135deg, #4facfe 0%, #00f2fe 100%);
    --gradient-warning: linear-gradient(135deg, #fa709a 0%, #fee140 100%);
    --gradient-purple: linear-gradient(135deg, #a8edea 0%, #fed6e3 100%);
    --gradient-mesh: radial-gradient(at 40% 20%, hsla(28,100%,74%,0.3) 0px, transparent 50%),
                      radial-gradient(at 80% 0%, hsla(189,100%,56%,0.3) 0px, transparent 50%),
                      radial-gradient(at 0% 50%, hsla(355,100%,93%,0.3) 0px, transparent 50%),
                      radial-gradient(at 80% 50%, hsla(340,100%,76%,0.3) 0px, transparent 50%),
                      radial-gradient(at 0% 100%, hsla(22,100%,77%,0.3) 0px, transparent 50%),
                      radial-gradient(at 80% 100%, hsla(242,100%,70%,0.3) 0px, transparent 50%),
                      radial-gradient(at 0% 0%, hsla(343,100%,76%,0.3) 0px, transparent 50%);

    /* Accent Colors */
    --color-accent-primary: #667eea;
    --color-accent-secondary: #764ba2;
    --color-accent-tertiary: #f093fb;
    --color-accent-glow: rgba(102, 126, 234, 0.5);

    /* Text Colors */
    --color-text-primary: #FFFFFF;
    --color-text-secondary: #D1D5DB;
    --color-text-tertiary: #9CA3AF;
    --color-text-muted: #6B7280;

    /* Status Colors */
    --color-success: #10B981;
    --color-success-glow: rgba(16, 185, 129, 0.3);
    --color-warning: #F59E0B;
    --color-warning-glow: rgba(245, 158, 11, 0.3);
    --color-error: #EF4444;
    --color-error-glow: rgba(239, 68, 68, 0.3);
    --color-info: #3B82F6;
    --color-info-glow: rgba(59, 130, 246, 0.3);

    /* Borders */
    --border-glass: 1px solid rgba(255, 255, 255, 0.1);
    --border-glass-strong: 1px solid rgba(255, 255, 255, 0.2);
    --border-accent: 1px solid var(--color-accent-primary);

    /* Spacing Scale - 8pt grid */
    --space-1: 4px;
    --space-2: 8px;
    --space-3: 12px;
    --space-4: 16px;
    --space-5: 20px;
    --space-6: 24px;
    --space-7: 32px;
    --space-8: 40px;
    --space-9: 48px;
    --space-10: 64px;
    --space-11: 80px;
    --space-12: 96px;

    /* Typography - Premium Fonts */
    --font-primary: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
    --font-display: 'Space Grotesk', 'Inter', sans-serif;
    --font-mono: 'SF Mono', 'Monaco', 'Cascadia Code', monospace;

    /* Font Sizes */
    --text-xs: 12px;
    --text-sm: 14px;
    --text-base: 16px;
    --text-lg: 18px;
    --text-xl: 20px;
    --text-2xl: 24px;
    --text-3xl: 30px;
    --text-4xl: 36px;
    --text-5xl: 48px;
    --text-6xl: 60px;

    /* Font Weights */
    --font-light: 300;
    --font-normal: 400;
    --font-medium: 500;
    --font-semibold: 600;
    --font-bold: 700;
    --font-extrabold: 800;

    /* Line Heights */
    --leading-tight: 1.25;
    --leading-snug: 1.375;
    --leading-normal: 1.5;
    --leading-relaxed: 1.625;
    --leading-loose: 2;

    /* Premium Shadows */
    --shadow-xs: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
    --shadow-sm: 0 2px 4px 0 rgba(0, 0, 0, 0.1);
    --shadow-md: 0 4px 8px 0 rgba(0, 0, 0, 0.15);
    --shadow-lg: 0 8px 16px 0 rgba(0, 0, 0, 0.2);
    --shadow-xl: 0 12px 24px 0 rgba(0, 0, 0, 0.25);
    --shadow-2xl: 0 16px 32px 0 rgba(0, 0, 0, 0.3);
    --shadow-inner: inset 0 2px 4px 0 rgba(0, 0, 0, 0.06);

    /* Glow Effects */
    --glow-primary: 0 0 20px var(--color-accent-glow);
    --glow-success: 0 0 20px var(--color-success-glow);
    --glow-warning: 0 0 20px var(--color-warning-glow);
    --glow-error: 0 0 20px var(--color-error-glow);
    --glow-strong: 0 0 40px var(--color-accent-glow);

    /* Border Radius */
    --radius-xs: 4px;
    --radius-sm: 8px;
    --radius-md: 12px;
    --radius-lg: 16px;
    --radius-xl: 20px;
    --radius-2xl: 24px;
    --radius-3xl: 32px;
    --radius-full: 9999px;

    /* Transitions - Smooth & Premium */
    --transition-fast: 150ms cubic-bezier(0.4, 0, 0.2, 1);
    --transition-base: 250ms cubic-bezier(0.4, 0, 0.2, 1);
    --transition-slow: 400ms cubic-bezier(0.4, 0, 0.2, 1);
    --transition-bounce: 600ms cubic-bezier(0.68, -0.55, 0.265, 1.55);

    /* Backdrop Blur */
    --blur-sm: blur(4px);
    --blur-md: blur(8px);
    --blur-lg: blur(16px);
    --blur-xl: blur(24px);

    /* Z-Index Scale */
    --z-base: 1;
    --z-dropdown: 100;
    --z-sticky: 200;
    --z-fixed: 300;
    --z-modal-backdrop: 400;
    --z-modal: 500;
    --z-toast: 600;
}

/* ==================== RESET & BASE ==================== */

*, *::before, *::after {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

html {
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
    text-rendering: optimizeLegibility;
    font-feature-settings: 'liga', 'kern';
    scroll-behavior: smooth;
}

body {
    font-family: var(--font-primary);
    font-size: var(--text-base);
    font-weight: var(--font-normal);
    line-height: var(--leading-normal);
    color: var(--color-text-primary);
    background: var(--color-bg-primary);
    background-image: var(--gradient-mesh);
    background-attachment: fixed;
    min-height: 100vh;
    overflow-x: hidden;
}

/* Selection Styling */
::selection {
    background: var(--color-accent-primary);
    color: white;
}

::-moz-selection {
    background: var(--color-accent-primary);
    color: white;
}

/* Scrollbar Styling */
::-webkit-scrollbar {
    width: 8px;
    height: 8px;
}

::-webkit-scrollbar-track {
    background: var(--color-bg-secondary);
}

::-webkit-scrollbar-thumb {
    background: var(--color-bg-elevated);
    border-radius: var(--radius-full);
    border: 2px solid var(--color-bg-secondary);
}

::-webkit-scrollbar-thumb:hover {
    background: var(--color-accent-primary);
}

/* ==================== LOADING SCREEN ==================== */

.loading-screen {
    position: fixed;
    inset: 0;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    background: var(--color-bg-primary);
    background-image: var(--gradient-mesh);
    z-index: var(--z-modal);
}

.loading-spinner {
    width: 60px;
    height: 60px;
    border: 4px solid rgba(255, 255, 255, 0.1);
    border-top-color: var(--color-accent-primary);
    border-radius: var(--radius-full);
    animation: spin 1s linear infinite;
}

@keyframes spin {
    to { transform: rotate(360deg); }
}

.loading-text {
    margin-top: var(--space-6);
    font-size: var(--text-lg);
    font-weight: var(--font-medium);
    color: var(--color-text-secondary);
    animation: pulse 2s ease-in-out infinite;
}

@keyframes pulse {
    0%, 100% { opacity: 1; }
    50% { opacity: 0.5; }
}

/* ==================== APP CONTAINER ==================== */

.app-container {
    min-height: 100vh;
    display: flex;
    flex-direction: column;
}

/* ==================== HEADER ==================== */

.app-header {
    position: sticky;
    top: 0;
    z-index: var(--z-sticky);
    background: var(--glass-bg-strong);
    backdrop-filter: var(--blur-lg);
    -webkit-backdrop-filter: var(--blur-lg);
    border-bottom: var(--border-glass);
    box-shadow: var(--shadow-md);
}

.header-content {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: var(--space-4) var(--space-6);
    max-width: 1200px;
    margin: 0 auto;
}

.header-left {
    display: flex;
    align-items: center;
    gap: var(--space-4);
}

.app-logo {
    font-family: var(--font-display);
    font-size: var(--text-2xl);
    font-weight: var(--font-bold);
    background: var(--gradient-primary);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
    letter-spacing: -0.02em;
}

.header-right {
    display: flex;
    align-items: center;
    gap: var(--space-3);
}

.icon-btn {
    position: relative;
    display: flex;
    align-items: center;
    justify-content: center;
    width: 40px;
    height: 40px;
    background: var(--glass-bg);
    border: var(--border-glass);
    border-radius: var(--radius-md);
    color: var(--color-text-secondary);
    cursor: pointer;
    transition: all var(--transition-base);
}

.icon-btn:hover {
    background: var(--glass-bg-strong);
    border-color: var(--color-accent-primary);
    color: var(--color-text-primary);
    transform: translateY(-2px);
    box-shadow: var(--glow-primary);
}

.icon-btn:active {
    transform: translateY(0);
}

.notification-badge {
    position: absolute;
    top: -4px;
    right: -4px;
    min-width: 18px;
    height: 18px;
    padding: 0 5px;
    background: var(--gradient-secondary);
    color: white;
    font-size: var(--text-xs);
    font-weight: var(--font-bold);
    border-radius: var(--radius-full);
    display: flex;
    align-items: center;
    justify-content: center;
    box-shadow: var(--shadow-md);
    animation: bounce-in 0.3s var(--transition-bounce);
}

@keyframes bounce-in {
    0% { transform: scale(0); }
    50% { transform: scale(1.2); }
    100% { transform: scale(1); }
}

/* Search Bar */
.search-bar {
    padding: 0 var(--space-6) var(--space-4);
    max-width: 1200px;
    margin: 0 auto;
    width: 100%;
}

.search-bar input {
    width: 100%;
    padding: var(--space-3) var(--space-4);
    background: var(--glass-bg);
    border: var(--border-glass);
    border-radius: var(--radius-lg);
    color: var(--color-text-primary);
    font-family: var(--font-primary);
    font-size: var(--text-base);
    outline: none;
    transition: all var(--transition-base);
}

.search-bar input:focus {
    background: var(--glass-bg-strong);
    border-color: var(--color-accent-primary);
    box-shadow: var(--glow-primary);
}

.search-bar input::placeholder {
    color: var(--color-text-muted);
}

.search-results {
    margin-top: var(--space-3);
    background: var(--glass-bg-strong);
    backdrop-filter: var(--blur-lg);
    border: var(--border-glass);
    border-radius: var(--radius-lg);
    box-shadow: var(--shadow-xl);
    max-height: 400px;
    overflow-y: auto;
}

/* ==================== TAB NAVIGATION ==================== */

.tab-nav {
    display: flex;
    gap: var(--space-2);
    padding: var(--space-4) var(--space-6);
    background: var(--glass-bg);
    border-bottom: var(--border-glass);
    overflow-x: auto;
    max-width: 1200px;
    margin: 0 auto;
    width: 100%;
}

.tab-btn {
    display: flex;
    align-items: center;
    gap: var(--space-2);
    padding: var(--space-3) var(--space-5);
    background: transparent;
    border: none;
    border-radius: var(--radius-lg);
    color: var(--color-text-tertiary);
    font-family: var(--font-primary);
    font-size: var(--text-sm);
    font-weight: var(--font-medium);
    cursor: pointer;
    transition: all var(--transition-base);
    white-space: nowrap;
}

.tab-btn svg {
    transition: all var(--transition-base);
}

.tab-btn:hover {
    background: var(--glass-bg);
    color: var(--color-text-secondary);
}

.tab-btn.active {
    background: var(--gradient-primary);
    color: white;
    box-shadow: var(--glow-primary);
}

.tab-btn.active svg {
    filter: drop-shadow(0 0 4px rgba(255, 255, 255, 0.5));
}

/* ==================== MAIN CONTENT ==================== */

.main-content {
    flex: 1;
    max-width: 1200px;
    margin: 0 auto;
    padding: var(--space-6);
    width: 100%;
}

.tab-content {
    display: none;
    animation: fadeIn 0.3s var(--transition-base);
}

.tab-content.active {
    display: block;
}

@keyframes fadeIn {
    from {
        opacity: 0;
        transform: translateY(10px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}

/* ==================== PREMIUM CARDS ==================== */

.section-card {
    background: var(--glass-bg-strong);
    backdrop-filter: var(--blur-lg);
    -webkit-backdrop-filter: var(--blur-lg);
    border: var(--border-glass);
    border-radius: var(--radius-xl);
    padding: var(--space-6);
    box-shadow: var(--shadow-xl);
    transition: all var(--transition-base);
}

.section-card:hover {
    border-color: var(--color-accent-primary);
    box-shadow: var(--shadow-2xl), var(--glow-primary);
    transform: translateY(-2px);
}

.card-elevated {
    background: var(--glass-bg);
    backdrop-filter: var(--blur-md);
    border: var(--border-glass);
    border-radius: var(--radius-lg);
    padding: var(--space-5);
    box-shadow: var(--shadow-lg);
}

/* ==================== PROFILE HERO ==================== */

.profile-hero {
    text-align: center;
    padding: var(--space-8) var(--space-6);
    background: var(--glass-bg-strong);
    backdrop-filter: var(--blur-xl);
    border: var(--border-glass);
    border-radius: var(--radius-2xl);
    box-shadow: var(--shadow-2xl);
    margin-bottom: var(--space-8);
    position: relative;
    overflow: hidden;
}

.profile-hero::before {
    content: '';
    position: absolute;
    top: -50%;
    left: -50%;
    width: 200%;
    height: 200%;
    background: var(--gradient-mesh);
    opacity: 0.3;
    animation: rotate 20s linear infinite;
    z-index: -1;
}

@keyframes rotate {
    from { transform: rotate(0deg); }
    to { transform: rotate(360deg); }
}

.profile-avatar-large {
    width: 120px;
    height: 120px;
    margin: 0 auto var(--space-5);
    position: relative;
}

.avatar-placeholder {
    width: 100%;
    height: 100%;
    background: var(--gradient-primary);
    border-radius: var(--radius-full);
    display: flex;
    align-items: center;
    justify-content: center;
    box-shadow: var(--shadow-xl), var(--glow-strong);
    border: 4px solid rgba(255, 255, 255, 0.1);
    animation: float 3s ease-in-out infinite;
}

@keyframes float {
    0%, 100% { transform: translateY(0px); }
    50% { transform: translateY(-10px); }
}

.avatar-placeholder svg {
    color: white;
}

.profile-name {
    font-family: var(--font-display);
    font-size: var(--text-3xl);
    font-weight: var(--font-bold);
    color: var(--color-text-primary);
    margin-bottom: var(--space-2);
    letter-spacing: -0.02em;
}

.profile-username {
    font-size: var(--text-lg);
    color: var(--color-text-tertiary);
    margin-bottom: var(--space-6);
}

.profile-stats-row {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
    gap: var(--space-4);
    margin-top: var(--space-6);
}

.stat-box {
    background: var(--glass-bg);
    border: var(--border-glass);
    border-radius: var(--radius-lg);
    padding: var(--space-5);
    transition: all var(--transition-base);
    cursor: pointer;
}

.stat-box:hover {
    background: var(--glass-bg-strong);
    border-color: var(--color-accent-primary);
    transform: translateY(-4px);
    box-shadow: var(--glow-primary);
}

.stat-value {
    font-family: var(--font-display);
    font-size: var(--text-3xl);
    font-weight: var(--font-bold);
    background: var(--gradient-primary);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
    margin-bottom: var(--space-2);
}

.stat-label {
    font-size: var(--text-sm);
    color: var(--color-text-tertiary);
    text-transform: uppercase;
    letter-spacing: 0.05em;
    font-weight: var(--font-medium);
}

/* ==================== BUTTONS ==================== */

.btn-primary {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: var(--space-2);
    padding: var(--space-4) var(--space-6);
    background: var(--gradient-primary);
    border: none;
    border-radius: var(--radius-lg);
    color: white;
    font-family: var(--font-primary);
    font-size: var(--text-base);
    font-weight: var(--font-semibold);
    cursor: pointer;
    transition: all var(--transition-base);
    box-shadow: var(--shadow-md);
    position: relative;
    overflow: hidden;
}

.btn-primary::before {
    content: '';
    position: absolute;
    top: 0;
    left: -100%;
    width: 100%;
    height: 100%;
    background: linear-gradient(90deg, transparent, rgba(255,255,255,0.2), transparent);
    transition: left 0.5s;
}

.btn-primary:hover::before {
    left: 100%;
}

.btn-primary:hover {
    transform: translateY(-2px);
    box-shadow: var(--shadow-xl), var(--glow-strong);
}

.btn-primary:active {
    transform: translateY(0);
}

.btn-secondary {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: var(--space-2);
    padding: var(--space-3) var(--space-5);
    background: var(--glass-bg);
    border: var(--border-glass);
    border-radius: var(--radius-md);
    color: var(--color-text-primary);
    font-family: var(--font-primary);
    font-size: var(--text-sm);
    font-weight: var(--font-medium);
    cursor: pointer;
    transition: all var(--transition-base);
}

.btn-secondary:hover {
    background: var(--glass-bg-strong);
    border-color: var(--color-accent-primary);
    transform: translateY(-2px);
    box-shadow: var(--glow-primary);
}

/* ==================== VOUCH CARDS ==================== */

.vouch-card {
    background: var(--glass-bg);
    border: var(--border-glass);
    border-radius: var(--radius-lg);
    padding: var(--space-4);
    transition: all var(--transition-base);
    cursor: pointer;
}

.vouch-card:hover {
    background: var(--glass-bg-strong);
    border-color: var(--color-accent-primary);
    transform: translateX(4px);
    box-shadow: var(--glow-primary);
}

.vouch-card-header {
    display: flex;
    align-items: center;
    gap: var(--space-3);
    margin-bottom: var(--space-3);
}

.vouch-avatar {
    width: 40px;
    height: 40px;
    background: var(--gradient-primary);
    border-radius: var(--radius-full);
    display: flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
    box-shadow: var(--shadow-md);
}

.vouch-info {
    flex: 1;
    min-width: 0;
}

.vouch-username {
    font-weight: var(--font-semibold);
    color: var(--color-text-primary);
    margin-bottom: var(--space-1);
}

.vouch-timestamp {
    font-size: var(--text-xs);
    color: var(--color-text-muted);
}

.vouch-comment {
    margin-top: var(--space-3);
    padding: var(--space-3);
    background: var(--glass-bg);
    border-radius: var(--radius-md);
    font-size: var(--text-sm);
    color: var(--color-text-secondary);
    font-style: italic;
}

/* ==================== BADGES & RANKS ==================== */

.badge-container {
    display: flex;
    flex-wrap: wrap;
    gap: var(--space-2);
    margin-top: var(--space-4);
}

.badge-item {
    display: inline-flex;
    align-items: center;
    gap: var(--space-2);
    padding: var(--space-2) var(--space-4);
    background: var(--glass-bg);
    border: var(--border-glass);
    border-radius: var(--radius-full);
    font-size: var(--text-sm);
    font-weight: var(--font-medium);
    color: var(--color-text-secondary);
    transition: all var(--transition-base);
    cursor: pointer;
}

.badge-item:hover {
    background: var(--glass-bg-strong);
    border-color: var(--color-accent-primary);
    transform: scale(1.05);
    box-shadow: var(--glow-primary);
}

/* ==================== LEADERBOARD ==================== */

.leaderboard-item {
    display: flex;
    align-items: center;
    gap: var(--space-4);
    padding: var(--space-4);
    background: var(--glass-bg);
    border: var(--border-glass);
    border-radius: var(--radius-lg);
    transition: all var(--transition-base);
    margin-bottom: var(--space-3);
}

.leaderboard-item:hover {
    background: var(--glass-bg-strong);
    border-color: var(--color-accent-primary);
    transform: translateX(8px);
    box-shadow: var(--glow-primary);
}

.leaderboard-rank {
    font-family: var(--font-display);
    font-size: var(--text-2xl);
    font-weight: var(--font-bold);
    background: var(--gradient-primary);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
    min-width: 40px;
}

.leaderboard-rank.top-1 {
    background: linear-gradient(135deg, #FFD700, #FFA500);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
}

.leaderboard-rank.top-2 {
    background: linear-gradient(135deg, #C0C0C0, #808080);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
}

.leaderboard-rank.top-3 {
    background: linear-gradient(135deg, #CD7F32, #8B4513);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
}

/* ==================== TOAST NOTIFICATIONS ==================== */

.toast {
    position: fixed;
    bottom: var(--space-6);
    right: var(--space-6);
    padding: var(--space-4) var(--space-6);
    background: var(--glass-bg-strong);
    backdrop-filter: var(--blur-xl);
    border: var(--border-glass);
    border-radius: var(--radius-lg);
    box-shadow: var(--shadow-2xl);
    color: var(--color-text-primary);
    font-size: var(--text-sm);
    font-weight: var(--font-medium);
    z-index: var(--z-toast);
    animation: slideInRight 0.3s var(--transition-bounce);
}

@keyframes slideInRight {
    from {
        transform: translateX(400px);
        opacity: 0;
    }
    to {
        transform: translateX(0);
        opacity: 1;
    }
}

.toast.success {
    border-color: var(--color-success);
    box-shadow: var(--shadow-2xl), var(--glow-success);
}

.toast.error {
    border-color: var(--color-error);
    box-shadow: var(--shadow-2xl), var(--glow-error);
}

/* ==================== EMPTY STATES ==================== */

.empty-state {
    text-align: center;
    padding: var(--space-10);
    color: var(--color-text-tertiary);
}

.empty-state-icon {
    font-size: var(--text-6xl);
    opacity: 0.5;
    margin-bottom: var(--space-4);
}

.empty-state-title {
    font-size: var(--text-xl);
    font-weight: var(--font-semibold);
    color: var(--color-text-secondary);
    margin-bottom: var(--space-2);
}

.empty-state-description {
    font-size: var(--text-base);
    color: var(--color-text-muted);
}

/* ==================== RESPONSIVE DESIGN ==================== */

@media (max-width: 768px) {
    .main-content {
        padding: var(--space-4);
    }

    .profile-hero {
        padding: var(--space-6) var(--space-4);
    }

    .profile-name {
        font-size: var(--text-2xl);
    }

    .profile-stats-row {
        grid-template-columns: 1fr 1fr;
    }

    .tab-nav {
        padding: var(--space-3) var(--space-4);
    }

    .tab-btn span {
        display: none;
    }

    .header-content {
        padding: var(--space-3) var(--space-4);
    }

    .app-logo {
        font-size: var(--text-xl);
    }
}

@media (max-width: 480px) {
    .profile-stats-row {
        grid-template-columns: 1fr;
    }
}

/* ==================== ACCESSIBILITY ==================== */

.sr-only {
    position: absolute;
    width: 1px;
    height: 1px;
    padding: 0;
    margin: -1px;
    overflow: hidden;
    clip: rect(0, 0, 0, 0);
    white-space: nowrap;
    border-width: 0;
}

/* Focus visible styles */
*:focus-visible {
    outline: 2px solid var(--color-accent-primary);
    outline-offset: 2px;
}

/* Reduced motion */
@media (prefers-reduced-motion: reduce) {
    *,
    *::before,
    *::after {
        animation-duration: 0.01ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: 0.01ms !important;
    }
}

