/* ==================== VOUCH BEACON STYLES ==================== */
/* Professional, sophisticated design system */

/* CSS Variables - Design Tokens */
:root {
    /* Color Palette - Professional Dark Theme */
    --color-bg-primary: #0A0E27;
    --color-bg-secondary: #141B3C;
    --color-bg-tertiary: #1E2749;
    --color-bg-card: #1A2238;

    --color-text-primary: #FFFFFF;
    --color-text-secondary: #B8C5D6;
    --color-text-tertiary: #7A8BA0;

    --color-accent-primary: #4F46E5;
    --color-accent-secondary: #6366F1;
    --color-accent-hover: #5B52F9;

    --color-success: #10B981;
    --color-warning: #F59E0B;
    --color-error: #EF4444;

    --color-border: rgba(255, 255, 255, 0.08);
    --color-border-hover: rgba(255, 255, 255, 0.15);

    /* Spacing Scale */
    --space-1: 4px;
    --space-2: 8px;
    --space-3: 12px;
    --space-4: 16px;
    --space-5: 24px;
    --space-6: 32px;
    --space-7: 48px;
    --space-8: 64px;

    /* Typography */
    --font-primary: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, sans-serif;
    --font-mono: 'SF Mono', Monaco, 'Cascadia Code', 'Roboto Mono', monospace;

    --text-xs: 11px;
    --text-sm: 13px;
    --text-base: 15px;
    --text-lg: 17px;
    --text-xl: 20px;
    --text-2xl: 24px;
    --text-3xl: 32px;

    --font-weight-normal: 400;
    --font-weight-medium: 500;
    --font-weight-semibold: 600;
    --font-weight-bold: 700;

    /* Shadows */
    --shadow-sm: 0 1px 2px rgba(0, 0, 0, 0.1);
    --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.3);
    --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.4);
    --shadow-xl: 0 20px 25px -5px rgba(0, 0, 0, 0.5);
    --shadow-glow: 0 0 20px rgba(79, 70, 229, 0.4);

    /* Border Radius */
    --radius-sm: 6px;
    --radius-md: 8px;
    --radius-lg: 12px;
    --radius-xl: 16px;
    --radius-full: 9999px;

    /* Transitions */
    --transition-fast: 150ms cubic-bezier(0.4, 0, 0.2, 1);
    --transition-base: 250ms cubic-bezier(0.4, 0, 0.2, 1);
    --transition-slow: 400ms cubic-bezier(0.4, 0, 0.2, 1);

    /* Z-Index Scale */
    --z-base: 1;
    --z-dropdown: 100;
    --z-sticky: 200;
    --z-modal: 300;
    --z-toast: 400;
}

/* ==================== RESET & BASE ==================== */

* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

html {
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
    text-rendering: optimizeLegibility;
}

body {
    font-family: var(--font-primary);
    font-size: var(--text-base);
    line-height: 1.5;
    color: var(--color-text-primary);
    background: var(--color-bg-primary);
    overflow-x: hidden;
}

button {
    font-family: inherit;
    cursor: pointer;
    border: none;
    background: none;
}

input, textarea {
    font-family: inherit;
}

/* ==================== LOADING SCREEN ==================== */

.loading-screen {
    position: fixed;
    inset: 0;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    background: var(--color-bg-primary);
    z-index: var(--z-modal);
}

.loading-spinner {
    width: 48px;
    height: 48px;
    border: 3px solid var(--color-bg-tertiary);
    border-top-color: var(--color-accent-primary);
    border-radius: 50%;
    animation: spin 0.8s linear infinite;
}

@keyframes spin {
    to { transform: rotate(360deg); }
}

.loading-text {
    margin-top: var(--space-4);
    font-size: var(--text-sm);
    color: var(--color-text-tertiary);
    letter-spacing: 0.05em;
    text-transform: uppercase;
}

/* ==================== APP CONTAINER ==================== */

.app-container {
    min-height: 100vh;
    display: flex;
    flex-direction: column;
}

/* ==================== HEADER ==================== */

.app-header {
    position: sticky;
    top: 0;
    z-index: var(--z-sticky);
    background: rgba(10, 14, 39, 0.95);
    backdrop-filter: blur(20px);
    -webkit-backdrop-filter: blur(20px);
    border-bottom: 1px solid var(--color-border);
}

.header-content {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: var(--space-4);
    max-width: 800px;
    margin: 0 auto;
}

.header-left {
    display: flex;
    align-items: center;
    gap: var(--space-3);
}

.app-logo {
    font-size: var(--text-xl);
    font-weight: var(--font-weight-bold);
    background: linear-gradient(135deg, #4F46E5 0%, #7C3AED 100%);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
    letter-spacing: -0.02em;
}

.header-right {
    display: flex;
    align-items: center;
    gap: var(--space-2);
}

.icon-btn {
    position: relative;
    display: flex;
    align-items: center;
    justify-content: center;
    width: 40px;
    height: 40px;
    border-radius: var(--radius-full);
    color: var(--color-text-secondary);
    background: transparent;
    transition: all var(--transition-fast);
}

.icon-btn:hover {
    color: var(--color-text-primary);
    background: var(--color-bg-tertiary);
}

.icon-btn:active {
    transform: scale(0.95);
}

.notification-badge {
    position: absolute;
    top: 6px;
    right: 6px;
    min-width: 18px;
    height: 18px;
    padding: 0 4px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 11px;
    font-weight: var(--font-weight-bold);
    color: white;
    background: var(--color-error);
    border-radius: var(--radius-full);
    border: 2px solid var(--color-bg-primary);
}

/* Search Bar */
.search-bar {
    padding: 0 var(--space-4) var(--space-4);
    max-width: 800px;
    margin: 0 auto;
}

.search-bar input {
    width: 100%;
    padding: var(--space-3) var(--space-4);
    font-size: var(--text-base);
    color: var(--color-text-primary);
    background: var(--color-bg-tertiary);
    border: 1px solid var(--color-border);
    border-radius: var(--radius-lg);
    transition: all var(--transition-fast);
}

.search-bar input:focus {
    outline: none;
    border-color: var(--color-accent-primary);
    box-shadow: 0 0 0 3px rgba(79, 70, 229, 0.1);
}

.search-results {
    margin-top: var(--space-2);
    background: var(--color-bg-card);
    border: 1px solid var(--color-border);
    border-radius: var(--radius-lg);
    overflow: hidden;
    max-height: 400px;
    overflow-y: auto;
}

/* ==================== TAB NAVIGATION ==================== */

.tab-nav {
    display: flex;
    background: var(--color-bg-secondary);
    border-bottom: 1px solid var(--color-border);
    overflow-x: auto;
    -webkit-overflow-scrolling: touch;
}

.tab-btn {
    flex: 1;
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: var(--space-1);
    padding: var(--space-3);
    font-size: var(--text-xs);
    font-weight: var(--font-weight-medium);
    color: var(--color-text-tertiary);
    background: transparent;
    border-bottom: 2px solid transparent;
    transition: all var(--transition-fast);
}

.tab-btn svg {
    opacity: 0.6;
    transition: opacity var(--transition-fast);
}

.tab-btn:hover {
    color: var(--color-text-secondary);
}

.tab-btn:hover svg {
    opacity: 0.8;
}

.tab-btn.active {
    color: var(--color-accent-primary);
    border-bottom-color: var(--color-accent-primary);
}

.tab-btn.active svg {
    opacity: 1;
}

/* ==================== MAIN CONTENT ==================== */

.main-content {
    flex: 1;
    padding: var(--space-5) var(--space-4);
    max-width: 800px;
    margin: 0 auto;
    width: 100%;
}

.tab-content {
    display: none;
    animation: fadeIn var(--transition-base);
}

.tab-content.active {
    display: block;
}

@keyframes fadeIn {
    from {
        opacity: 0;
        transform: translateY(10px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}

/* ==================== PROFILE HERO ==================== */

.profile-hero {
    text-align: center;
    padding: var(--space-6) 0;
}

.profile-avatar-large {
    display: inline-block;
    margin-bottom: var(--space-4);
}

.avatar-placeholder {
    width: 96px;
    height: 96px;
    display: flex;
    align-items: center;
    justify-content: center;
    background: linear-gradient(135deg, var(--color-accent-primary), var(--color-accent-secondary));
    border-radius: var(--radius-full);
    color: white;
    box-shadow: var(--shadow-xl);
}

.profile-name {
    font-size: var(--text-3xl);
    font-weight: var(--font-weight-bold);
    margin-bottom: var(--space-1);
    letter-spacing: -0.02em;
}

.profile-username {
    font-size: var(--text-base);
    color: var(--color-text-tertiary);
    margin-bottom: var(--space-5);
}

.profile-stats-row {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: var(--space-4);
    margin-bottom: var(--space-5);
}

.stat-box {
    padding: var(--space-4);
    background: var(--color-bg-card);
    border: 1px solid var(--color-border);
    border-radius: var(--radius-lg);
    transition: all var(--transition-fast);
}

.stat-box:hover {
    border-color: var(--color-border-hover);
    transform: translateY(-2px);
}

.stat-value {
    font-size: var(--text-3xl);
    font-weight: var(--font-weight-bold);
    background: linear-gradient(135deg, var(--color-accent-primary), var(--color-accent-secondary));
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
    margin-bottom: var(--space-1);
}

.stat-label {
    font-size: var(--text-sm);
    color: var(--color-text-tertiary);
}

.profile-actions {
    display: flex;
    justify-content: center;
    gap: var(--space-3);
}

/* ==================== BUTTONS ==================== */

.btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: var(--space-2);
    padding: var(--space-3) var(--space-5);
    font-size: var(--text-base);
    font-weight: var(--font-weight-semibold);
    border-radius: var(--radius-lg);
    transition: all var(--transition-fast);
    position: relative;
    overflow: hidden;
}

.btn::before {
    content: '';
    position: absolute;
    inset: 0;
    background: rgba(255, 255, 255, 0.1);
    opacity: 0;
    transition: opacity var(--transition-fast);
}

.btn:hover::before {
    opacity: 1;
}

.btn:active {
    transform: scale(0.98);
}

.btn-primary {
    color: white;
    background: linear-gradient(135deg, var(--color-accent-primary), var(--color-accent-secondary));
    box-shadow: var(--shadow-md);
}

.btn-primary:hover {
    box-shadow: var(--shadow-lg), var(--shadow-glow);
}

.btn-secondary {
    color: var(--color-text-primary);
    background: var(--color-bg-card);
    border: 1px solid var(--color-border);
}

.btn-secondary:hover {
    border-color: var(--color-border-hover);
}

/* ==================== SECTIONS ==================== */

.section-container {
    margin-bottom: var(--space-6);
}

.section-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    margin-bottom: var(--space-4);
}

.section-title {
    font-size: var(--text-xl);
    font-weight: var(--font-weight-bold);
    letter-spacing: -0.01em;
}

.section-count {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-width: 28px;
    height: 28px;
    padding: 0 var(--space-2);
    font-size: var(--text-sm);
    font-weight: var(--font-weight-bold);
    color: var(--color-text-primary);
    background: var(--color-bg-tertiary);
    border-radius: var(--radius-full);
}

/* ==================== VOUCHES LIST ==================== */

.vouches-list {
    display: flex;
    flex-direction: column;
    gap: var(--space-3);
}

.vouch-card {
    padding: var(--space-4);
    background: var(--color-bg-card);
    border: 1px solid var(--color-border);
    border-radius: var(--radius-lg);
    transition: all var(--transition-fast);
    cursor: pointer;
}

.vouch-card:hover {
    border-color: var(--color-border-hover);
    transform: translateX(4px);
    box-shadow: var(--shadow-md);
}

.vouch-card-header {
    display: flex;
    align-items: center;
    gap: var(--space-3);
    margin-bottom: var(--space-2);
}

.vouch-avatar {
    width: 40px;
    height: 40px;
    display: flex;
    align-items: center;
    justify-content: center;
    background: linear-gradient(135deg, var(--color-accent-primary), var(--color-accent-secondary));
    border-radius: var(--radius-full);
    color: white;
    font-size: var(--text-sm);
    font-weight: var(--font-weight-bold);
}

.vouch-user-info {
    flex: 1;
}

.vouch-username {
    font-size: var(--text-base);
    font-weight: var(--font-weight-semibold);
    color: var(--color-text-primary);
}

.vouch-time {
    font-size: var(--text-sm);
    color: var(--color-text-tertiary);
}

.vouch-comment {
    font-size: var(--text-base);
    color: var(--color-text-secondary);
    line-height: 1.6;
    margin-top: var(--space-2);
    padding-left: 52px;
}

.vouch-actions {
    display: flex;
    gap: var(--space-2);
    margin-top: var(--space-3);
    padding-left: 52px;
}

.vouch-action-btn {
    padding: var(--space-2) var(--space-3);
    font-size: var(--text-sm);
    font-weight: var(--font-weight-medium);
    color: var(--color-text-tertiary);
    background: var(--color-bg-tertiary);
    border-radius: var(--radius-md);
    transition: all var(--transition-fast);
}

.vouch-action-btn:hover {
    color: var(--color-text-primary);
    background: var(--color-bg-secondary);
}

/* ==================== LEADERBOARD ==================== */

.leaderboard-tabs {
    display: flex;
    gap: var(--space-2);
    margin-bottom: var(--space-4);
    padding: var(--space-1);
    background: var(--color-bg-secondary);
    border-radius: var(--radius-lg);
}

.lb-tab-btn {
    flex: 1;
    padding: var(--space-3);
    font-size: var(--text-sm);
    font-weight: var(--font-weight-semibold);
    color: var(--color-text-secondary);
    background: transparent;
    border-radius: var(--radius-md);
    transition: all var(--transition-fast);
}

.lb-tab-btn:hover {
    color: var(--color-text-primary);
}

.lb-tab-btn.active {
    color: white;
    background: var(--color-accent-primary);
    box-shadow: var(--shadow-md);
}

.leaderboard-list {
    display: flex;
    flex-direction: column;
    gap: var(--space-2);
}

.leaderboard-item {
    display: flex;
    align-items: center;
    gap: var(--space-4);
    padding: var(--space-4);
    background: var(--color-bg-card);
    border: 1px solid var(--color-border);
    border-radius: var(--radius-lg);
    transition: all var(--transition-fast);
    cursor: pointer;
}

.leaderboard-item:hover {
    border-color: var(--color-border-hover);
    transform: translateX(4px);
}

.leaderboard-rank {
    width: 32px;
    height: 32px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: var(--text-lg);
    font-weight: var(--font-weight-bold);
    color: var(--color-text-tertiary);
}

.leaderboard-item:nth-child(1) .leaderboard-rank {
    color: #FFD700;
}

.leaderboard-item:nth-child(2) .leaderboard-rank {
    color: #C0C0C0;
}

.leaderboard-item:nth-child(3) .leaderboard-rank {
    color: #CD7F32;
}

.leaderboard-avatar {
    width: 48px;
    height: 48px;
    display: flex;
    align-items: center;
    justify-content: center;
    background: linear-gradient(135deg, var(--color-accent-primary), var(--color-accent-secondary));
    border-radius: var(--radius-full);
    color: white;
    font-size: var(--text-base);
    font-weight: var(--font-weight-bold);
}

.leaderboard-info {
    flex: 1;
}

.leaderboard-name {
    font-size: var(--text-base);
    font-weight: var(--font-weight-semibold);
    color: var(--color-text-primary);
}

.leaderboard-username {
    font-size: var(--text-sm);
    color: var(--color-text-tertiary);
}

.leaderboard-score {
    font-size: var(--text-xl);
    font-weight: var(--font-weight-bold);
    color: var(--color-accent-primary);
}

/* ==================== NETWORK VISUALIZATION ==================== */

.network-info {
    margin-bottom: var(--space-4);
    padding: var(--space-4);
    font-size: var(--text-sm);
    color: var(--color-text-secondary);
    background: var(--color-bg-card);
    border: 1px solid var(--color-border);
    border-radius: var(--radius-lg);
}

.network-visualization {
    width: 100%;
    height: 500px;
    background: var(--color-bg-card);
    border: 1px solid var(--color-border);
    border-radius: var(--radius-lg);
    overflow: hidden;
    position: relative;
}

.network-legend {
    display: flex;
    justify-content: center;
    gap: var(--space-5);
    margin-top: var(--space-4);
    padding: var(--space-3);
    background: var(--color-bg-card);
    border: 1px solid var(--color-border);
    border-radius: var(--radius-lg);
}

.legend-item {
    display: flex;
    align-items: center;
    gap: var(--space-2);
    font-size: var(--text-sm);
    color: var(--color-text-secondary);
}

.legend-dot {
    width: 12px;
    height: 12px;
    border-radius: 50%;
}

.legend-you {
    background: var(--color-accent-primary);
    box-shadow: 0 0 8px var(--color-accent-primary);
}

.legend-vouched {
    background: var(--color-success);
}

.legend-voucher {
    background: var(--color-warning);
}

/* ==================== SKELETON LOADING ==================== */

.skeleton-card {
    height: 100px;
    background: linear-gradient(
        90deg,
        var(--color-bg-card) 0%,
        var(--color-bg-tertiary) 50%,
        var(--color-bg-card) 100%
    );
    background-size: 200% 100%;
    border-radius: var(--radius-lg);
    animation: shimmer 1.5s infinite;
}

@keyframes shimmer {
    0% {
        background-position: -200% 0;
    }
    100% {
        background-position: 200% 0;
    }
}

/* ==================== TOAST NOTIFICATIONS ==================== */

.toast-container {
    position: fixed;
    bottom: var(--space-5);
    left: 50%;
    transform: translateX(-50%);
    z-index: var(--z-toast);
    display: flex;
    flex-direction: column;
    gap: var(--space-2);
    pointer-events: none;
}

.toast {
    min-width: 280px;
    padding: var(--space-4);
    font-size: var(--text-sm);
    color: white;
    background: var(--color-bg-card);
    border: 1px solid var(--color-border);
    border-radius: var(--radius-lg);
    box-shadow: var(--shadow-xl);
    animation: toastSlideUp var(--transition-base);
    pointer-events: auto;
}

.toast.success {
    background: var(--color-success);
}

.toast.error {
    background: var(--color-error);
}

@keyframes toastSlideUp {
    from {
        opacity: 0;
        transform: translateY(20px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}

/* ==================== EMPTY STATES ==================== */

.empty-state {
    padding: var(--space-8) var(--space-4);
    text-align: center;
}

.empty-state-icon {
    width: 64px;
    height: 64px;
    margin: 0 auto var(--space-4);
    color: var(--color-text-tertiary);
    opacity: 0.3;
}

.empty-state-title {
    font-size: var(--text-xl);
    font-weight: var(--font-weight-semibold);
    color: var(--color-text-primary);
    margin-bottom: var(--space-2);
}

.empty-state-text {
    font-size: var(--text-base);
    color: var(--color-text-tertiary);
}

/* ==================== RESPONSIVE ==================== */

@media (max-width: 640px) {
    :root {
        --text-xs: 10px;
        --text-sm: 12px;
        --text-base: 14px;
        --text-lg: 16px;
        --text-xl: 18px;
        --text-2xl: 22px;
        --text-3xl: 28px;
    }

    .main-content {
        padding: var(--space-4) var(--space-3);
    }

    .profile-stats-row {
        grid-template-columns: 1fr;
    }

    .network-visualization {
        height: 400px;
    }
}

/* ==================== UTILITIES ==================== */

.text-center { text-align: center; }
.text-left { text-align: left; }
.text-right { text-align: right; }

.mt-1 { margin-top: var(--space-1); }
.mt-2 { margin-top: var(--space-2); }
.mt-3 { margin-top: var(--space-3); }
.mt-4 { margin-top: var(--space-4); }
.mt-5 { margin-top: var(--space-5); }

.mb-1 { margin-bottom: var(--space-1); }
.mb-2 { margin-bottom: var(--space-2); }
.mb-3 { margin-bottom: var(--space-3); }
.mb-4 { margin-bottom: var(--space-4); }
.mb-5 { margin-bottom: var(--space-5); }
